/* ---- src\js\02-helpers.js ---- */
/* =====================================================================
   HELPERS
   ===================================================================== */
function unitName(i) { // 0:K 1:M 2:B 3:T then aa..zz
  if (i < 4) return ['K', 'M', 'B', 'T'][i];
  const j = i - 4; return String.fromCharCode(97 + Math.floor(j / 26) % 26) + String.fromCharCode(97 + j % 26);
}
function fmt(n) {
  if (!Number.isFinite(n)) return n > 0 ? '∞' : '0';
  const neg = n < 0; n = Math.abs(n);
  let s;
  if (n < 1000) s = '' + Math.floor(n);
  else {
    let i = Math.floor(Math.log10(n) / 3) - 1;
    let v = n / Math.pow(1000, i + 1);
    if (v >= 1000) { v /= 1000; i++; } if (v < 1) { v *= 1000; i--; }
    if (i >= 4 + 676) s = n.toExponential(2);
    else s = (v < 10 ? (Math.floor(v * 100) / 100).toFixed(2) : v < 100 ? (Math.floor(v * 10) / 10).toFixed(1) : Math.floor(v)) + unitName(i);
  }
  return (neg ? '-' : '') + s;
}
function earn(g, inRun = true) {
  if (!(g > 0)) return;
  if (inRun && run && !run.pvp && typeof liveEmberMult === 'function') g *= liveEmberMult(); // (0.30.1: a live event's bonus, nights only)
  meta.embers += g; meta.stats.earned += g;
  if (inRun && run) run.embers += g;
}
const fmt1 = n => (n < 10 ? (Math.floor(n * 10) / 10).toFixed(1) : fmt(n));
function dur(s) { s = Math.max(0, Math.floor(s)); const h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60);
  return h ? `${h}h ${m}m` : m ? `${m} min` : `${s} sec`; }
const rnd = (a, b) => a + Math.random() * (b - a);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
function hexA(hex, a) { const n = parseInt(hex.slice(1), 16); return `rgba(${n >> 16 & 255},${n >> 8 & 255},${n & 255},${a})`; }
function setT(el, v) { if (el._t !== v) { el._t = v; el.textContent = v; } }

const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]); // text from a save, before it goes into innerHTML

/* ---- src\js\02b-icons.js ---- */
/* =====================================================================
   ICONS (0.16.1): one set of pictures, the same on every platform.
   Emoji are drawn by the operating system (Segoe UI Emoji on Windows, Noto Color Emoji on Android, others elsewhere), so
   the same "🔥" looked different in the desktop app and the Android app, and some symbols were missing on some systems.
   The game now draws its own:
   - ico(id) gives an inline SVG for a canonical icon id ('fire', 'swords', 'laugh'...); sized 1.15em, so an icon never
     changes the width of the text around it more than a letter would.
   - Every emoji or symbol the game uses maps to an id (EMO_ID). A watcher swaps any of them that reach the page for the
     game's icon, wherever it came from (menus, the HUD, toasts, chat), and keeps the character as hidden text for
     screen readers and for code that reads the text back.
   - Reactions are sent and stored by id (see PVP_REACTS in 15-pvp.js); the picture is chosen here.
   Unknown emoji (typed in chat, say) are left to the system font, which every platform has.
   ===================================================================== */
