  angry: face(`<path d="M6.8 9 10 10.4M17.2 9 14 10.4" stroke="${IC_INK}" stroke-width="1.5" stroke-linecap="round"/><circle cx="9" cy="12" r="1.1" fill="${IC_INK}"/><circle cx="15" cy="12" r="1.1" fill="${IC_INK}"/><path d="M8.8 17q3.2-2.4 6.4 0" stroke="${IC_INK}" stroke-width="1.5" fill="none" stroke-linecap="round"/><path d="M1.5 16.5q1.8-1.2 3.4.2-1.4 1.6-3.4-.2zM22.5 16.5q-1.8-1.2-3.4.2 1.4 1.6 3.4-.2z" fill="#dfe7f5"/>`, '#ff9a5a', '#c0572a'),
