function discover(kind, id) { // records a first sighting (and says so during play)
  if (!meta.codex[kind] || meta.codex[kind][id]) return;
  meta.codex[kind][id] = 1; meta.codexNew = 1;
  if (typeof Replay !== 'undefined' && Replay.on) return;
  const name = kind === 'c' ? (CODEX_C.find(x => x.id === id) || {}).name : kind === 'b' ? (BOSSES.find(x => x.id === id) || {}).name : kind === 'ev' ? (EVK[id] || {}).title : kind === 'l' ? (allLandmarks().find(x => x.id === id) || {}).name : '';
  if (name) toastQ.push(['New Codex entry', name]);
}

