/* ---------- Shop catalogue (categories) ----------
   Weapons and keepers with a price can be bought; the rest unlock by clearing regions or through achievements. */
const STORE_CATS = [['all', 'All'], ['weapon', 'Weapons'], ['keeper', 'Keepers'], ['charm', 'Charms'], ['look', 'Cosmetics'], ['supplies', 'Supplies'], ['lumens', 'Lumens'], ['support', 'Supporter']];
function storeItems() {
  const out = [];
  for (const w of WEAPONS) if (w.id !== 'lantern') out.push({ cat: 'weapon', key: 'w:' + w.id, name: w.name, sub: w.rarity, col: RARITY[w.rarity], desc: w.trait, price: w.price, unlock: w.unlock, owned: !!meta.arsenal.owned[w.id] });
  for (const k of KEEPERS) if (k.id !== 'keeper') out.push({ cat: 'keeper', key: 'k:' + k.id, name: k.name, sub: k.abName, desc: k.stats.join(', '), price: k.price, unlock: k.unlock, owned: !!meta.keepers.owned[k.id] });
  for (const l of LIGHTHOUSES) if (l.price) out.push({ cat: 'look', key: 'h:' + l.id, name: l.name, sub: 'Lighthouse', desc: l.desc, price: l.price, owned: lhOwned(l) });
  for (const c of CHARMS) out.push({ cat: 'charm', key: 'c:' + c.id, name: c.name, sub: 'Charm', desc: c.desc, price: c.price, unlock: c.unlock, owned: !!meta.charms.owned[c.id] });
  for (const [slot, label] of LOOK_SLOTS) for (const it of LOOKS[slot]) if (!lookFree(slot, it) && !it.sku && !it.fest && !it.ev) out.push({ cat: 'look', key: 'l:' + slot + ':' + it.id, name: it.name, sub: label, col: it.col, price: it.price, ach: it.ach, owned: lookOwned(slot, it) });
  return out;
}
// One item a day is 25% off (same for everyone on the same date).
function dailyDeal() {
  const d = new Date(), seed = d.getFullYear() * 1000 + d.getMonth() * 40 + d.getDate();
  const pool = storeItems().filter(i => i.price && !i.owned);
  return pool.length ? pool[Math.floor(mulberry32(seed)() * pool.length)].key : null;
}
const itemPrice = it => it.key === dailyDeal() ? Math.ceil(it.price * .75) : it.price;

/* ---------- Validate the content-dependent parts of the save (runs once, after the tables above exist) ---------- */
function sanitizeMeta() {
  const a = meta.raw_arsenal, k = meta.raw_keepers, l = meta.raw_look, w = meta.raw_world, ch = meta.raw_charms;
  const cx = meta.raw_codex;
  if (cx) for (const kk of ['c', 'b', 'ev', 'l']) if (cx[kk] && typeof cx[kk] === 'object') for (const id in cx[kk]) if (cx[kk][id]) meta.codex[kk][String(id)] = 1;
  if (ch) {
    if (ch.owned) for (const id in ch.owned) if (CHK[id] && ch.owned[id]) meta.charms.owned[id] = 1;
    if (Array.isArray(ch.slots)) meta.charms.slots = ch.slots.filter((id, i, arr) => CHK[id] && meta.charms.owned[id] && arr.indexOf(id) === i).slice(0, CHARM_SLOTS);
  }
  if (a) {
    if (a.owned) for (const id in a.owned) if (WPK[id] && a.owned[id]) meta.arsenal.owned[id] = 1;
    if (a.lv) for (const id in a.lv) if (WPK[id]) meta.arsenal.lv[id] = Math.floor(num(a.lv[id], 1, 1, WEAPON_MAX_LV));
    if (WPK[a.equip] && meta.arsenal.owned[a.equip]) meta.arsenal.equip = a.equip;
  }
  for (const id in meta.arsenal.owned) if (!meta.arsenal.lv[id]) meta.arsenal.lv[id] = 1;
  if (k) {
    if (k.owned) for (const id in k.owned) if (KPK[id] && k.owned[id]) meta.keepers.owned[id] = 1;
    if (KPK[k.equip] && meta.keepers.owned[k.equip]) meta.keepers.equip = k.equip;
  }
  if (l) {
    if (l.owned) for (const key in l.owned) { const [slot, id] = key.split(':'); if (LOOKS[slot] && LOOKS[slot].some(i => i.id === id)) meta.look.owned[key] = 1; }
    for (const [slot] of LOOK_SLOTS) { const it = LOOKS[slot].find(i => i.id === l[slot]); if (it && lookOwned(slot, it)) meta.look[slot] = it.id; }
  }
  if (w) {
    for (const f of ['unlocked', 'cleared']) if (w[f]) for (const id in w[f]) if (RGK[id] && w[f][id]) meta.world[f][id] = 1;
    if (w.acts && typeof w.acts === 'object') for (const k in w.acts) if (/^(in|out)[1-5]$/.test(k) && w.acts[k]) meta.world.acts[k] = 1;
    meta.world.campaign = w.campaign ? 1 : 0;
    if (w.stars) for (const id in w.stars) if (RGK[id] && w.stars[id] && typeof w.stars[id] === 'object')
      meta.world.stars[id] = { clear: !!w.stars[id].clear, norepair: !!w.stars[id].norepair, strong: !!w.stars[id].strong };
  }
  // region rewards are always granted to anyone who has cleared the region (also repairs edited or partial saves)
  for (const r of REGIONS) if (meta.world.cleared[r.id]) grantRegionReward(r, true);
  unlockRegions(); // 0.14: regions open along the map's paths
  // 0.10: names that fail the rules fall back to the default; unknown ids fall back too
  if (meta.mastery) for (const k in meta.mastery) if (!WPK[k]) delete meta.mastery[k];
  delete meta.raw_arsenal; delete meta.raw_keepers; delete meta.raw_look; delete meta.raw_world; delete meta.raw_charms; delete meta.raw_codex;
}
function grantRegionReward(r, silent) {
  const got = [];
  if (r.reward.weapon && !meta.arsenal.owned[r.reward.weapon]) { meta.arsenal.owned[r.reward.weapon] = 1; meta.arsenal.lv[r.reward.weapon] = 1; got.push(WPK[r.reward.weapon].name); }
  if (r.reward.keeper && !meta.keepers.owned[r.reward.keeper]) { meta.keepers.owned[r.reward.keeper] = 1; got.push(KPK[r.reward.keeper].name); }
  if (r.reward.charm && !meta.charms.owned[r.reward.charm]) { meta.charms.owned[r.reward.charm] = 1; got.push(CHK[r.reward.charm].name); }
  return silent ? [] : got;
}
// sanitizeMeta() runs at the end of 04c-depths.js, once the 0.12 content exists

