  roninshade:  { name: 'Wandering blade', look: 'shade', col: '#c86a7a', hp: 30, spd: 44, r: 13, dmg: 12, em: 4, traits: ['dash', 'armor'], desc: 'A shade in lacquered armour, fast in bursts.', tip: 'Taps and fire ignore its armour.' },
  cloudserpent:{ name: 'Cloud serpent', look: 'drifter', col: '#d6e8ff', hp: 22, spd: 48, r: 12, dmg: 9, em: 3, traits: ['sway'], desc: 'Coils through the clouds around the peaks.', tip: 'Wide volleys catch its weaving.' },
  stoneguard:  { name: 'Stone guardian', look: 'rimeback', col: '#a8a4b8', hp: 60, spd: 22, r: 17, dmg: 16, em: 6, traits: ['frostproof', 'armor'], desc: 'A temple guardian that forgot what it guards.', tip: 'Slows slide off it. Fire and taps work.' },
  forgeling:   { name: 'Forgeling', look: 'cinderling', col: '#ff9040', hp: 14, spd: 70, r: 9, dmg: 7, em: 2, traits: ['fireproof'], desc: 'A spark from the imperial forges.', tip: 'Fire feeds it. Use bolts.' },
  ironlegion:  { name: 'Iron legionary', look: 'hulk', col: '#8a8290', hp: 80, spd: 20, r: 19, dmg: 18, em: 6, traits: ['shell', 'armor'], desc: 'Marches in step, shield raised.', tip: 'Crack the shield with taps or explosions first.' },
