/* ---------- Ambience: a quiet sea-and-wind bed made from filtered noise (no audio files) ---------- */
const Amb = { nodes: null, t: 0 };
function ambStart() {
  if (!Sfx.c || Amb.nodes || !Sfx.noiseBuf) return;
  const c = Sfx.c, src = c.createBufferSource(); src.buffer = Sfx.noiseBuf; src.loop = true;
  const sea = c.createBiquadFilter(); sea.type = 'lowpass'; sea.frequency.value = 420;
  const wind = c.createBiquadFilter(); wind.type = 'bandpass'; wind.frequency.value = 900; wind.Q.value = .6;
  const gSea = c.createGain(), gWind = c.createGain(), out = c.createGain();
  gSea.gain.value = 0; gWind.gain.value = 0; out.gain.value = 0;
  src.connect(sea); sea.connect(gSea); src.connect(wind); wind.connect(gWind); gSea.connect(out); gWind.connect(out); out.connect(Sfx.out);
  src.start(); Amb.nodes = { gSea, gWind, out, wind };
}
function ambTick(dt) {
  if (Sfx.probe || !Sfx.c) return; // an offline level probe is rendering: stay off its audio graph
  if (!Amb.nodes) { if (Sfx.c && Sfx.c.state === 'running') ambStart(); return; }
  Amb.t += dt;
  const st = meta.settings, on = st.amb && !st.muted && !Replay.on, now = Sfx.c.currentTime;
  const reg = run && run.exp ? run.exp.region : 'fog', storm = reg === 'storm' ? 1.8 : 1;
  const wave = .5 + .5 * Math.sin(Amb.t * .55) * Math.sin(Amb.t * .23 + 1); // slow swells
  Amb.nodes.out.gain.setTargetAtTime(on ? .09 * volOf('amb') : 0, now, .4);
  Amb.nodes.gSea.gain.setTargetAtTime(.5 + wave * .7, now, .3);
  Amb.nodes.gWind.gain.setTargetAtTime((.12 + .1 * Math.sin(Amb.t * .9)) * storm, now, .5);
  Amb.nodes.wind.frequency.setTargetAtTime(reg === 'drowned' ? 520 : 900 + 300 * Math.sin(Amb.t * .3), now, .5);
}

