/* ---------- Weekly goals: three per week, the same for everyone, progress counted from the week's start ---------- */
const WEEKLY_POOL = [
  { id: 'kills', text: n => `Defeat ${fmt(n)} creatures`, n: [600, 900, 1200], stat: () => meta.stats.kills },
  { id: 'bosses', text: n => `Defeat ${n} bosses`, n: [4, 6, 8], stat: () => meta.bossKills },
  { id: 'elites', text: n => `Defeat ${n} elite creatures`, n: [15, 25, 40], stat: () => meta.stats.elites },
  { id: 'taps', text: n => `Land ${fmt(n)} taps`, n: [300, 500, 800], stat: () => meta.stats.taps },
  { id: 'nights', text: n => `Play ${n} nights`, n: [5, 8, 12], stat: () => meta.runs },
  { id: 'regions', text: n => `Clear ${n} region${n > 1 ? 's' : ''}`, n: [1, 2, 3], stat: () => meta.stats.regions },
];
function weekKey() { const d = new Date(), j = new Date(d.getFullYear(), 0, 1), w = Math.floor(((d - j) / 864e5 + j.getDay()) / 7); return `${d.getFullYear()}-W${w}`; }
function weeklyGoals() {
  const key = weekKey();
  if (meta.weekly.key !== key) { // new week: fresh goals, progress counted from here
    meta.weekly = { key, base: Object.fromEntries(WEEKLY_POOL.map(g => [g.id, g.stat()])), claimed: {} }; save();
  }
  let h = 2166136261; for (const ch of key) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); }
  const R = mulberry32(h >>> 0), pool = WEEKLY_POOL.slice(), out = [];
  while (out.length < 3) { const g = pool.splice(Math.floor(R() * pool.length), 1)[0]; const n = g.n[Math.floor(R() * g.n.length)]; out.push({ id: g.id, text: g.text(n), n, cur: Math.max(0, g.stat() - (meta.weekly.base[g.id] || 0)) }); }
  return out;
}

