// Banners: the night sky, one for each region cleared (in its own colours), and a few for milestones.
const BANNERS = [{ id: 'night', name: 'Night sky', sky: ['#0b1028', '#222f5e', '#3a4b86'] }]
  .concat(REGIONS.map(r => ({ id: r.id, name: r.name, how: 'Clear ' + r.name, ok: () => rgClear(r.id), sky: r.pal.sky })))
  .concat([{ id: 'dawn', name: 'First dawn', how: 'Reach level 25', ok: () => PLV() >= 25, sky: ['#2a2350', '#8a5a7a', '#f0b27a'] },
    { id: 'supporter', name: 'Lantern gold', sku: SKU.supporter, sky: ['#3a2410', '#8a5a2c', '#f0c36a'] }]);
// Badges: achievements worth showing off. The player pins up to three; otherwise the three hardest earned show.
const BADGES = REGIONS.map(r => ({ id: 'r-' + r.id, name: r.name, how: 'Clear ' + r.name, ok: () => rgClear(r.id), mark: r.num }))
  .concat([
    { id: 'slayer', name: 'Guardian Slayer', how: 'Defeat 10 bosses', ok: () => meta.bossKills >= 10, mark: '10' },
    { id: 'rush', name: 'Boss Rush', how: 'Survive the Boss Rush', ok: () => meta.records.bossRush > 0, mark: 'BR' },
    { id: 'wave50', name: 'Fifty Waves', how: 'Reach wave 50 in Endless', ok: () => Math.max(meta.records.wave, meta.best) >= 50, mark: '50' },
    { id: 'master', name: 'Weapon Master', how: 'Master a weapon (level 5 mastery)', ok: () => Object.values(meta.mastery).some(k => masteryLv(k) >= 5), mark: 'M' },
    { id: 'arsenal', name: 'Full Arsenal', how: 'Own every weapon', ok: () => WEAPONS.every(w => meta.arsenal.owned[w.id]), mark: 'A' },
    { id: 'relit3', name: 'Thrice Relit', how: 'Relight the lighthouse 3 times', ok: () => meta.prestige.count >= 3, mark: 'III' },
    { id: 'ascend5', name: 'Ascendant', how: 'Conquer Ascension 5', ok: () => meta.asc.max >= 5, mark: 'A5' },
    { id: 'achiever', name: 'Achiever', how: 'Earn half of all achievements', ok: () => Object.keys(meta.ach).length >= Math.ceil(ACH.length / 2), mark: '★' },
    { id: 'supporter', name: 'Supporter', sku: SKU.supporter, mark: '♥' },
  ]);
const PF = { avatar: AVATARS, frame: FRAMES, banner: BANNERS };
const pfOwned = it => it.sku ? entitled(it.sku) : !it.ok || it.ok();
const pfPick = kind => { const it = PF[kind].find(x => x.id === meta.profile[kind]); return it && pfOwned(it) ? it : PF[kind][0]; };
const badgesEarned = () => BADGES.filter(pfOwned);
function badgesShown() {
  const pinned = meta.profile.badges.map(id => BADGES.find(b => b.id === id)).filter(b => b && pfOwned(b));
  return pinned.length ? pinned : badgesEarned().slice(-3).reverse();
}
const avatarSvg = (a, size = 48) => `<svg viewBox="0 0 16 16" width="${size}" height="${size}" shape-rendering="crispEdges" aria-hidden="true"><g fill="currentColor">${a.px.map(r => `<rect x="${r[0]}" y="${r[1]}" width="${r[2]}" height="${r[3]}"/>`).join('')}</g><g fill="var(--pfAcc)">${a.acc.map(r => `<rect x="${r[0]}" y="${r[1]}" width="${r[2]}" height="${r[3]}"/>`).join('')}</g></svg>`;
const bannerCss = b => `linear-gradient(115deg, ${b.sky[0]}, ${b.sky[1]} 55%, ${b.sky[2]})`;
// The weapon, keeper and region played longest (by time), for the profile.
function favourites() {
  const top = (o, table) => { let best = '', t = 0; for (const k in o) if (o[k] > t && table[k]) { best = k; t = o[k]; } return best ? table[best].name : ''; };
  const U = meta.stats.use;
  return { w: top(U.w, WPK), k: top(U.k, KPK), r: top(U.r, RGK) };
}
// What the server shows on the public profile (checked again there: paid items need an entitlement).
const showcase = () => ({ badges: badgesShown().map(b => b.id), lh: { id: curLH().id, name: meta.lighthouse.name }, fav: favourites(), feats: featShowcase() }); // 0.14: feats
// Every paid item in the game, by SKU, in the server's "kind:id" form (compared with rules.js SKU_ITEMS by the tests).
function skuItems() {
  const out = {}, add = (sku, item) => { (out[sku] = out[sku] || []).push(item); };
  for (const [slot] of LOOK_SLOTS) for (const it of LOOKS[slot]) if (it.sku) add(it.sku, `look:${slot}:${it.id}`);
  for (const l of LIGHTHOUSES) if (l.sku) add(l.sku, 'lh:' + l.id);
  for (const kind in PF) for (const it of PF[kind]) if (it.sku) add(it.sku, `${kind}:${it.id}`);
  for (const b of BADGES) if (b.sku) add(b.sku, 'badge:' + b.id);
  for (const k in out) out[k].sort();
  return out;
}

// A small drawing of the home lighthouse for the profile card.
function drawMiniLH(c, l, lk = null) { // lk: someone else's looks { stripe, beam } (colours); by default your own
  const stripeC = lk && lk.stripe || lookOf('stripe').col, beamC = lk && lk.beam || lookOf('beam').col;
  const x = c.getContext('2d'), W = c.width, H = c.height; x.clearRect(0, 0, W, H);
  const top = H * (l.tall ? .14 : .2), bot = H * .92, wT = W * .2, wB = W * .34, cx = W / 2;
  const g = x.createRadialGradient(cx, top, 2, cx, top, W * .6); g.addColorStop(0, hexA(beamC, .55)); g.addColorStop(1, hexA(beamC, 0));
  x.fillStyle = g; x.fillRect(0, 0, W, H);
  x.fillStyle = l.body; x.beginPath(); x.moveTo(cx - wT, top + 12); x.lineTo(cx + wT, top + 12); x.lineTo(cx + wB, bot); x.lineTo(cx - wB, bot); x.closePath(); x.fill();
  x.save(); x.clip(); x.fillStyle = stripeC; // the same colour as the tower in the game (10-render.js)
  const span = bot - top - 12;
  // the same bands as the tower in the game: three stripes, or two bands
  if (l.pattern === 'stripes') for (let i = 0; i < 3; i++) x.fillRect(0, top + 12 + span * (.14 + i * .29), W, span * .13);
  else if (l.pattern === 'bands') { x.fillRect(0, top + 12 + span * .08, W, span * .06); x.fillRect(0, top + 12 + span * .55, W, span * .05); }
  else if (l.pattern === 'bricks') { x.globalAlpha = .35; for (let y = top + 16; y < bot; y += 7) x.fillRect(0, y, W, 1.5); x.globalAlpha = 1; }
  x.restore();
  x.fillStyle = l.trim; x.fillRect(cx - wT - 3, top + 8, wT * 2 + 6, 5); x.fillRect(cx - wT * .7, top - 6, wT * 1.4, 4);
  x.fillStyle = beamC; x.fillRect(cx - wT * .55, top - 2, wT * 1.1, 10);
  if (l.snow) { x.fillStyle = '#ffffff'; x.fillRect(cx - wT * .8, top - 9, wT * 1.6, 3); }
}

/* ---- src\js\07h-tides.js ---- */
/* =====================================================================
   TIDES (0.13): new route stops, events and chains, hazards, boss phases and synergies (data in 04d-tides.js).
   Everything random here draws from the night's seeded generator (rr) or the route's seed, so replays and
   co-op stay in step.
   ===================================================================== */

/* ---------- route stops ---------- */
// Mystery stops hold something fixed by the route's seed; the Cartographer's chart shows it in advance.
function mysteryOf(layer, i) {
  let r = mulberry32((run.exp.seed ^ 0x9e3779b9) + layer * 97 + i * 13)();
  for (const [t, p] of MYSTERY_OUT) { if (r < p) return t; r -= p; }
  return 'event';
}
const mapWhole = () => (meta.tides.map || 0) >= 3;
// Which event waits at an event stop: a chain step if one is due (at most one per expedition), otherwise one that fits here.
function eventFor(layer, i, mystery) {
  const R = mulberry32(run.exp.seed + layer * 31 + i), T = meta.tides;
  const due = EVENTS.filter(e => e.chain && (!e.ok || e.ok()) && (e.chain === 'lost' ? T.lost === e.step - 1 && !run.exp.chainSeen : mystery && (T.map || 0) < 3));
  const roll = R();
  if (due.length && roll < (mystery ? .6 : .4)) { if (due[0].chain === 'lost') run.exp.chainSeen = 1; return due[0].id; }
  const pool = EVENTS.filter(e => !e.chain && !e.hidden && (!e.ok || e.ok()));
  return pool[Math.floor(R() * pool.length)].id;
}
// Called by the ROUTE command for the stops added in 0.13. Returns true when it handled the stop.
function tideRoute(t, n, c) {
  const X = run.exp;
  if (t === 'ambush' || t === 'rescue') {
    X.left = 2; X.rescueMin = 1; enterFight(); show(null); startWave();
    if (t === 'rescue') banner('A crew is stranded', 'Keep the tower above half health for 2 waves', true);
    else banner('Ambush!', 'They come from every side', true);
    return true;
  }
  if (t === 'merchant') { X.left = 0; openMerchant(); return true; }
  if (t === 'story') {
    X.left = 0; const lms = LANDMARKS[X.region] || LANDMARKS.fog, li = mulberry32(X.seed + 7)() * lms.length | 0, [lname, lore] = lms[li];
    discover('l', landmarkId(X.region, li)); // 0.14: every landmark has a name and a page in the Codex
    const fix = heal(.12); sfx('collect');
    showResult(`Landmark: ${lname}`, lore, `You rest a moment. +${fmt(fix)} tower health.`);
    return true;
  }
  return false;
}
// A fight stop begins: the effects promised for "the next fight" apply to it.
function enterFight() {
  const X = run.exp;
  X.mods = { calm: X.calm || 0, loud: X.loud || 0, bonus: X.bonus || 0, safe: X.safe || 0, curse: X.curse ? 2 : 0 };
  X.calm = X.loud = X.bonus = X.safe = X.curse = 0;
}
const fightMods = () => (run && run.exp && run.exp.mods) || {};
// Embers: ambushes pay 50% more; a studied chart doubles a fight; a ringing buoy adds a quarter
const tideEm = () => !run || !run.exp ? 1 : (run.exp.node === 'ambush' ? 1.5 : 1) * (fightMods().bonus ? 2 : 1) * (fightMods().loud ? 1.25 : 1);
function payEv(k) { const c = Math.ceil(k * Math.max(1, ew()) * emMult()); run.embers = Math.max(0, run.embers - c); meta.embers = Math.max(0, meta.embers - c); return c; }

/* ---------- the merchant (uses the event screen, with a third button to leave) ---------- */
function merchantWares() {
  const R = mulberry32((run.exp.seed ^ 0x51ed) + run.exp.at[0] * 131 + run.exp.at[1] * 17), pool = WARES.filter(w => !w.ok || w.ok()), out = [];
  while (out.length < 2 && pool.length) out.push(pool.splice(Math.floor(R() * pool.length), 1)[0]);
  return out;
}
function openMerchant() {
  mode = 'route'; run.where = 'event'; run.exp.ev = 'merchant'; snapshot(false);
  const E = EVK.merchant, wares = merchantWares();
  $('#evT').textContent = E.title; $('#evText').textContent = `${E.text} You have ${fmt(run.embers)} embers from this expedition.`;
  $('#evChoices').hidden = false; $('#evResult').hidden = true; $('#bEvDone').hidden = true;
  [$('#evA'), $('#evB')].forEach((btn, j) => {
    const w = wares[j]; btn.hidden = !w; if (!w) return;
    const cost = wareCost(w);
    btn.querySelector('.nm').textContent = w.name; btn.querySelector('p').textContent = `${w.desc} ${fmt(cost)} embers.`;
    btn.disabled = run.embers < cost; btn.onclick = () => Cmd.dispatch({ t: 'EVENT', choice: j ? 'b' : 'a' });
  });
  const c3 = $('#evC'); c3.hidden = false; c3.disabled = false; c3.querySelector('.nm').textContent = 'Leave'; c3.querySelector('p').textContent = 'Keep your embers.';
  c3.onclick = () => Cmd.dispatch({ t: 'EVENT', choice: 'c' });
  show('event');
}
function merchantBuy(choice) {
  const X = run.exp; X.ev = null;
  if (choice === 'c') { sfx('reroll'); return showResult('The merchant', 'The trader tips a cap and rows off into the fog.', 'You keep your embers.'); }
  const w = merchantWares()[choice === 'b' ? 1 : 0]; if (!w) return openRoute();
  const cost = wareCost(w); if (run.embers < cost) return openMerchant();
  run.embers -= cost; meta.embers = Math.max(0, meta.embers - cost); meta.tides.merchants++; sfx('buy');
  let out = '';
  if (w.id === 'mend') out = `+${fmt(heal(.35))} tower health.`;
  else if (w.id === 'rerolls') { run.rerolls += 2; out = '+2 rerolls.'; }
  else if (w.id === 'powder') { run.s.dmg *= 1.1; out = '+10% damage for this expedition.'; }
  else if (w.id === 'upgrade') { X.pend = 'pick'; out = 'Choose a free upgrade next.'; }
  else if (w.id === 'relic') { X.pend = 'relic'; out = 'Choose a relic next.'; }
  showResult('The merchant', `You buy ${w.name.toLowerCase()} for ${fmt(cost)} embers.`, out);
}
// Continue after an event result: a promised upgrade or relic comes first, then the route.
function tideContinue() {
  const X = run.exp, p = X.pend; X.pend = '';
  if (p === 'pick') { X.left = 0; run.where = ''; showPick('treasure'); return true; }
  if (p === 'relic' && run.relics.length < relicSlots()) { openRelic(relicOffer(1), 'treasure'); return true; }
  return false;
}
// The new events' outcomes (the original five keep their own code in 07b-expedition.js).
function runTideEvent(E, a) {
  if (a && E.needs && !E.needs()) return false;
  if (a && E.cost && run.embers < Math.ceil(E.cost * Math.max(1, ew()) * emMult())) return false;
  const r = E.run(a) || {};
  run.exp.ev = null; sfx(a ? 'pick' : 'reroll');
  if (r.pick) run.exp.pend = 'pick'; else if (r.relic) run.exp.pend = 'relic';
  checkAch(); // chains and counters can complete achievements
  showResult(E.title, E.text, r.text || 'You move on.');
  return true;
}
// Event screen extras for the new events: costs, conditions, and hiding the merchant's third button.
function tideEventUi(e) {
  $('#evC').hidden = true; $('#evA').hidden = $('#evB').hidden = false;
  if (e.cost) { const c = Math.ceil(e.cost * Math.max(1, ew()) * emMult()); $('#evA').querySelector('p').textContent = `Costs ${fmt(c)} of this expedition's embers. ${e.a[1].replace(/^Costs embers\. ?/, '')}`; $('#evA').disabled = run.embers < c; }
  if (e.needs && !e.needs()) $('#evA').disabled = true;
}

/* ---------- waves: counts, hazards, rescue ---------- */
function tideWaveStart() {
  run.hz = null; run.blackout = 0; if (run.surge) endSurge(); ashWaveStart();
  const X = run.exp, node = X ? X.node : '', M = fightMods();
  if (node === 'ambush') { run.spawnLeft = Math.ceil(run.spawnLeft * 1.35); run.spawnGap *= .8; }
  if (M.loud) run.spawnLeft = Math.ceil(run.spawnLeft * 1.25);
  // hazards: expedition fights in the regions that have them, and Endless from wave 15
  const list = X ? (M.safe || node === 'boss' ? [] : REGION_HAZARDS[X.region] || []) : !run.bossRush && !run.daily && ew() >= 15 ? Object.keys(HAZARDS) : [];
  run.hzList = list.length && (X || rr() < .35) ? list : null;
  run.hzT = run.hzList ? rrnd(10, 20) : 0;
}
function tideSpawned(e) {
  const M = fightMods();
  if (M.calm) e.spd *= .85;
  if (M.curse > 0 && !e.boss && e.type !== 'orb') { M.curse--; makeElite(e); }
  if (e.boss) e.phaseMarks = 0;
}
