  if (run.blackout > 0) run.blackout -= dt;
  if (run.surge > 0) {
    run.surge -= dt; const C = G.core, near = (120 * U) ** 2;
    for (const e of run.enemies) if (!e.boss && e.type !== 'mistling') e.faded = (e.x - C.x) ** 2 + (e.y - C.y) ** 2 > near;
    if (run.surge <= 0) endSurge();
  }
