for (const r of WORLD_REGIONS) LANDMARKS[r.id] = r.landmarks;
const landmarkId = (region, i) => region + ':' + i;
function allLandmarks() { const out = []; for (const r of REGIONS) (LANDMARKS[r.id] || []).forEach(([name, lore], i) => out.push({ id: landmarkId(r.id, i), name, lore, region: r })); return out; }

/* ---------- the campaign: act cards, the ending ---------- */
function actIntro(regionId) { // the first time an act's first region is entered
  const act = actOf(regionId); meta.world.acts = meta.world.acts || {};
  if (meta.world.acts['in' + act.n] || act.regions[0] !== regionId || Replay.on) return null;
  meta.world.acts['in' + act.n] = 1; save(); return act;
}
function actOutro(regionId) { // the first time every region of an act is cleared
  const act = actOf(regionId); meta.world.acts = meta.world.acts || {};
  if (meta.world.acts['out' + act.n] || !act.regions.every(id => meta.world.cleared[id])) return null;
  meta.world.acts['out' + act.n] = 1; return act;
}

