  { const b = $('#bRelight'), pr = meta.prestige; b.disabled = !canRelight() && !pr.total;
    b.textContent = canRelight() ? `Relight the lighthouse (${shardsNow()} Light Shards)` : pr.total ? `Light Shard upgrades (${pr.shards} shards)` : 'Relight the lighthouse: clear Storm Waters or reach wave 30'; }
