      `<p class="eff">${l ? `<span>Now</span> ${d.eff(l)}` : ''}${l && !maxed ? '<br>' : ''}${maxed ? '' : `<span>Next</span> ${d.eff(l + 1)}`}</p></div>`;
    const b = document.createElement('button'); b.className = 'btn buy';
