const MUTE_SVG = on => on
  ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M16 9a4 4 0 0 1 0 6M19 6a8 8 0 0 1 0 12"/></svg>'
  : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M17 9l5 6M22 9l-5 6"/></svg>';
function applyVolume() { if (!Sfx.out || Sfx.probe) return; Sfx.out.gain.value = MASTER * (meta.settings.quiet ? .4 : 1); if (Sfx.fx) Sfx.fx.gain.value = volOf('sfx'); if (Sfx.ui) Sfx.ui.gain.value = volOf('ui'); }
