  $('#gfxNote').textContent = { auto: 'High detail, lowered only if the game runs slowly', low: 'Lowest detail, smoothest on older phones', medium: 'A balance for most phones and laptops', high: 'Full detail', ultra: 'Extra sharp on high-resolution screens', custom: 'Your own resolution and effects' }[st.gfx];
  $('#rowsCustom').hidden = st.gfx !== 'custom';
  for (const s of document.querySelectorAll('[data-sel]')) s.value = String(st[s.dataset.sel]);
