/* ---- src\js\09e-tides-ui.js ---- */
/* =====================================================================
   TIDES (0.13) on screen: route icons and Mystery stops, how hard each region is, achievements, titles, weekly goals.
   ===================================================================== */
Object.assign(ICON, {
  ambush: '<path d="M4 4l6 6M20 4l-6 6M4 20l6-6M20 20l-6-6M9 12h6"/>',
  merchant: '<path d="M5 9h14l-1.5 10h-11zM9 9V7a3 3 0 0 1 6 0v2"/>',
  mystery: '<path d="M12 3 21 12 12 21 3 12zM10 10a2 2 0 1 1 2.8 1.8c-.5.3-.8.7-.8 1.2M12 16v.3"/>',
  rescue: '<path d="M12 4a8 8 0 1 0 0 16 8 8 0 0 0 0-16zM12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM6.3 6.3l2.9 2.9M17.7 6.3l-2.9 2.9M6.3 17.7l2.9-2.9M17.7 17.7l-2.9-2.9"/>',
  story: '<path d="M8 21V5l4-2 4 2v16M6 21h12M10 9h4M10 13h4"/>',
});
// What a route stop shows: a Mystery reveals itself once visited, or always once the Cartographer's chart is whole.
function nodeShown(n, l, i) {
  if (n.t !== 'mystery' || !(n.done || mapWhole())) return { t: n.t, name: NODE[n.t].name, desc: NODE[n.t].desc };
  const t = mysteryOf(l, i); return { t, name: 'Mystery: ' + NODE[t].name, desc: NODE[t].desc };
}

/* ---------- how hard a region is, in the game's own numbers ---------- */
// Creatures in an expedition are as strong as Endless wave (wave here + the region's offset); the guardian comes after
// about two and a half waves a stop.
function regionThreat(r) {
  const start = 1 + r.off, guard = r.off + Math.round((r.rows || 6) * 2.5), best = Math.max(meta.best, meta.records.wave);
  const verdict = meta.world.cleared[r.id] ? 'Cleared before' : best >= guard ? 'You look ready' : best >= start + 6 ? 'A real challenge' : 'Very tough for now';
  return { start, guard, verdict, pips: Math.min(5, 1 + Math.floor(r.off / 3.5)) };
}

