  chal(`r.${g}.relics`, 'Regions', g, 'Relic keeper', `Clear ${nm} carrying three or more relics.`, a + 1, h => clearOf(h, g) && h.relics >= 3);
  chal(`r.${g}.lantern`, 'Regions', g, 'The first lantern', `Clear ${nm} with the starting lantern.`, a + 2, h => clearOf(h, g) && h.wpn === 'lantern');
  chal(`r.${g}.native`, 'Regions', g, 'A local keeper', `Clear ${nm} as ${(KEEPERS.find(k => k.unlock === g) || KPK.keeper).name}.`, a + 1, h => clearOf(h, g) && h.kpr === (KEEPERS.find(k => k.unlock === g) || KPK.keeper).id);
