[[20, 1], [30, 3], [40, 5], [50, 6]].forEach(([n, t]) => chal(`e.bare${n}`, 'Endless', 'endless', `Bare hands: wave ${n}`, `Reach wave ${n} in Endless with no charms.`, t, h => h.endless && h.charms === 0 && h.wave >= n));
