  chal(`a.${n}.bare`, 'Ascension', 'asc' + n, `Ascension ${n}: bare hands`, `Reach wave 25 on Ascension ${n} with no charms.`, t + 1, h => h.asc === n && h.wave >= 25 && h.charms === 0);
  chal(`a.${n}.common`, 'Ascension', 'asc' + n, `Ascension ${n}: humble light`, `Reach wave 25 on Ascension ${n} with a Common weapon.`, t + 2, h => h.asc === n && h.wave >= 25 && h.rarity === 'Common');
