  const counts = {}; for (const c of ACH_CATS) counts[c] = ACH.filter(a => a.cat === c && meta.ach[a.id]).length;
  const list = rows.filter(r => featCat === 'all' || r.steps[0].cat === featCat).filter(r => { const all = r.steps.every(a => meta.ach[a.id]); return featShow === 'all' || (featShow === 'got' ? r.steps.some(a => meta.ach[a.id]) : !all); });
  const shown = new Set(F().show.a);
