    const got = r.steps.map(a => !!meta.ach[a.id]), next = r.steps.find(a => !meta.ach[a.id]) || r.steps[r.steps.length - 1], done = !next || meta.ach[next.id];
    const top = [...r.steps].reverse().find(a => meta.ach[a.id]);
