  if (c.cat === 'Guardians') return c.group === 'bossrush' ? 'Boss Rush' : (BOSSES.find(b => b.id === c.group) || {}).name || c.group; if (c.cat === 'Ascension') return 'Ascension ' + c.group.slice(3);
