  const m = Math.hypot(dx, dz); if (m > 1) { dx /= m; dz /= m; }
  if (dx || dz) { const sp = 6.5 * (c.sens || 1); B.me.x = Math.max(-5, Math.min(B.limitX(), B.me.x + dx * sp * dt)); B.me.z = Math.max(-3, Math.min(BZ_HALF - .6, B.me.z + dz * sp * dt)); B.me.face = Math.atan2(dx, dz); }
