    for (const o of B.others.values()) { o.pos.x += (o.to.x - o.pos.x) * Math.min(1, dt * 8); o.pos.z += (o.to.z - o.pos.z) * Math.min(1, dt * 8); o.mesh.position.set(o.pos.x, 0, o.pos.z); o.mesh.rotation.y = o.face || 0; }
