    if (frost) { ctx.strokeStyle = 'rgba(160,215,255,.55)'; ctx.lineDashOffset = time * 20; ctx.beginPath(); ctx.arc(C.x, C.y, R - (fire ? 4 : 0), 0, 7); ctx.stroke(); }
