    const R = 58 * U + Math.sin(time * 3) * 2;
    ctx.fillStyle = 'rgba(159,216,255,.06)'; ctx.strokeStyle = 'rgba(159,216,255,.5)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(C.x, C.y, R, 0, 7); ctx.fill(); ctx.stroke();
