  c.strokeStyle = e.phase === 2 ? '#fff6c8' : 'rgba(232,240,255,.7)'; c.lineWidth = 2; c.beginPath(); // crown of sparks
  for (let i = -2; i <= 2; i++) { const bx = i * r * .28, by = -r * .95; c.moveTo(bx, by); c.lineTo(bx + 3, by - r * .3); c.lineTo(bx - 2, by - r * .38); c.lineTo(bx + 2, by - r * .62); }
  c.stroke();
