    const R = mulberry32(b.seed | 0); let px = b.x + (R() - .5) * 60 * U, py = -10;
    ctx.strokeStyle = `rgba(232,240,255,${b.life / .22})`; ctx.lineWidth = 3.5 * Math.max(.8, U); ctx.beginPath(); ctx.moveTo(px, py);
    const n = 9; for (let i = 1; i <= n; i++) { const t = i / n; px = b.x + (R() - .5) * 46 * U * (1 - t); py = -10 + (b.y + 10) * t; ctx.lineTo(px, py); }
    ctx.stroke();
    const gs = 90 * U; ctx.drawImage(glow('#e8f0ff'), b.x - gs / 2, b.y - gs / 2, gs, gs);
