  if (d === 'pea') { c.fillStyle = C.col2 || '#d4ad57'; for (let i = 0; i < 3; i++) { R(-2.2, -18 + i * 3.6, 1.1, 1.1); R(1.1, -18 + i * 3.6, 1.1, 1.1); } c.fillStyle = dark; poly([[-2.8, -20], [0, -16.5], [2.8, -20]]); }
  if (d === 'knit') { c.fillStyle = C.col2 || shade(col, .82); for (let yy = -18.5; yy < -8; yy += 2) R(-5, yy, 10, .6); R(-3.2, -20.6, 6.4, 1.6); } // cable-knit ribbing, a rolled neck
  if (d === 'robe') { c.fillStyle = C.col2 || '#d4ad57'; poly([[-4.6, -15], [4.6, -12.2], [4.6, -11], [-4.6, -13.8]]); R(1.5, -12, 1, 6); } // a sash
  if (d === 'great') { c.fillStyle = dark; poly([[-4.6, -19.4], [-3.4, -23.2], [3.4, -23.2], [4.6, -19.4]]); c.fillStyle = C.col2 || shade(col, .6); R(-1.4, -17, 1, 1); R(-1.4, -13, 1, 1); R(-1.4, -9, 1, 1); } // the tall collar
  if (d === 'cloak') { c.fillStyle = dark; R(-.3, -19, .6, 16); } // the cloak's opening
