/* ---------- backdrops, baked into the background layer ---------- */
function drawFrozenBackdrop(x, sy) {
  // aurora: soft green and violet ribbons high in the sky
  for (const [col, y0, amp] of [['rgba(120,255,190,.10)', .12, .05], ['rgba(170,140,255,.08)', .2, .04]]) {
    x.fillStyle = col; x.beginPath(); x.moveTo(0, H * y0);
    for (let i = 0; i <= 24; i++) x.lineTo(W * i / 24, H * (y0 + Math.sin(i * .7) * amp));
    for (let i = 24; i >= 0; i--) x.lineTo(W * i / 24, H * (y0 + .07 + Math.sin(i * .7 + .8) * amp));
    x.fill();
  }
  // icebergs on the horizon
  x.fillStyle = '#d6e6f0';
  for (const [px, w, h] of [[.04, 60, 34], [.2, 34, 22], [.72, 70, 46], [.88, 40, 26]]) {
    const bx = W * px; x.beginPath(); x.moveTo(bx, sy); x.lineTo(bx + w * .2 * U, sy - h * U); x.lineTo(bx + w * .45 * U, sy - h * .75 * U); x.lineTo(bx + w * .65 * U, sy - h * 1.05 * U); x.lineTo(bx + w * U, sy); x.fill();
  }
  x.fillStyle = 'rgba(120,160,190,.35)'; for (const px of [.04, .72]) x.fillRect(W * px, sy - 6 * U, 60 * U, 6 * U); // their shadows in the water
}
function drawDeepBackdrop(x, sy) {
  x.fillStyle = '#050d14'; // jagged sea stacks
  for (const [px, w, h] of [[.02, 30, 80], [.1, 18, 48], [.8, 26, 90], [.9, 20, 56]]) {
    const bx = W * px; x.beginPath(); x.moveTo(bx, sy); x.lineTo(bx + w * .3 * U, sy - h * U); x.lineTo(bx + w * .55 * U, sy - h * .8 * U); x.lineTo(bx + w * .75 * U, sy - h * .95 * U); x.lineTo(bx + w * U, sy); x.fill();
  }
  const R = mulberry32(77); x.fillStyle = 'rgba(95,200,210,.35)'; // things glowing far below
  for (let i = 0; i < 26; i++) { const px = R() * W, py = sy + R() * (H - sy); x.fillRect(px, py, 2, 2); }
}

/* ---------- live effects: snow, Whiteout, frozen lantern, boss warnings ---------- */
function drawDepthEffects(dt) {
  if (!run) return;
  drawTideEffects(); // 0.13 hazards (07h-tides.js)
  drawAshEffects(dt); // 0.13 ash, false lights, rooted lamp (10d-ashmarsh.js)
  drawCoopOverlay(); // 0.14 co-op lanes
  drawWorldEffects(dt); // 0.14 region mechanics, festival fireworks
  if (run.weather === 'snow' && !reduceMotion && !lowFx) {
    ctx.fillStyle = 'rgba(240,248,255,.75)';
    const fast = run.squall > 0 ? 2.6 : 1;
    for (const d of run.rain) {
      d.y += dt * .12 * d.l * fast; d.x += dt * (.02 + Math.sin(time + d.l * 9) * .02) * fast; if (d.y > 1) { d.y = 0; d.x = Math.random(); } if (d.x > 1) d.x -= 1;
      ctx.fillRect(d.x * W, d.y * H, 2 * d.l, 2 * d.l);
    }
  }
  if (run.squall > 0) { // Whiteout: everything beyond the lantern's reach disappears into the snow
    const R = squallR(), C = G.core, a = Math.min(1, run.squall / .6, (6 - run.squall) / .6) * .72;
    const g = ctx.createRadialGradient(C.x, C.y, R * .82, C.x, C.y, R * 1.25);
    g.addColorStop(0, 'rgba(230,242,252,0)'); g.addColorStop(1, `rgba(230,242,252,${a})`);
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  }
  if (run.frozenT > 0) { const s = 90 * U; ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = Math.min(1, run.frozenT); ctx.drawImage(glow('#d6f3ff'), G.lamp.x - s / 2, G.lamp.y - s / 2, s, s); ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over'; }
  for (const e of run.enemies) {
    if (!e.boss || e.dead) continue;
    if (e.breath > 0) { // the Wyrm's breath is coming: a line of frost toward the lamp
      ctx.strokeStyle = `rgba(214,243,255,${.25 + (1 - e.breath / 1.1) * .6})`; ctx.lineWidth = 3 * U; ctx.setLineDash([8, 6]);
      ctx.beginPath(); ctx.moveTo(e.x, e.y + e.r * .2); ctx.lineTo(G.lamp.x, G.lamp.y); ctx.stroke(); ctx.setLineDash([]);
    }
    if (e.gape > 0) { // the Maw's bite: a ring that closes, and how many taps are left
      const f = Math.max(0, e.gape / 1.8), R = e.r * (1.4 + f);
      ctx.strokeStyle = 'rgba(255,211,107,.85)'; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(e.x, e.y, R, -Math.PI / 2, -Math.PI / 2 + f * 6.283); ctx.stroke();
      ctx.fillStyle = '#ffd36b'; ctx.textAlign = 'center'; cfont(18, .9);
      ctx.fillText(`Tap! ${Math.max(0, 4 - (e.bitten || 0))}`, e.x, e.y - R - 6);
    }
  }
}

