    ctx.fillStyle = '#1a0a06'; ctx.beginPath(); ctx.ellipse(0, r * .35, r * .8, r * .32 + Math.sin(time * 3) * r * .05, 0, 0, 7); ctx.fill();
    ctx.fillStyle = '#ff8a4a'; for (let i = -3; i <= 3; i++) ctx.fillRect(i * r * .2 - 2, r * .3 + Math.sin(time * 6 + i) * 2, 4, 4);
    ctx.fillStyle = B.eye; for (const s of [-1, 1]) { ctx.beginPath(); ctx.arc(s * r * .45, -r * .25, r * .14 * (1 + Math.sin(time * 4) * .15), 0, 7); ctx.fill(); }
    if (e.phase === 2) { ctx.strokeStyle = 'rgba(255,138,74,.45)'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(0, 0, r * 1.6 + Math.sin(time * 6) * 3, 0, 7); ctx.stroke(); }
    return;
