    ctx.strokeStyle = 'rgba(200,230,180,.6)'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(s * r * .9, -r * .2); ctx.lineTo(lx, ly - r * .2); ctx.stroke();
    const g = glow('#d8ff9a'), gs = r * 1.2; ctx.drawImage(g, lx - gs / 2, ly - gs / 2, gs, gs); ctx.fillStyle = '#e8ffc8'; ctx.fillRect(lx - 3, ly - 4, 6, 8);
