// Ash drifting down, burning patches, false lights, and reeds around a rooted lamp.
function drawAshEffects(dt) {
  if (!run) return;
  if (run.weather === 'ash' && !reduceMotion && !lowFx) {
    for (const d of run.rain) {
      d.y += dt * .06 * d.l; d.x += dt * Math.sin(time * .7 + d.l * 9) * .01; if (d.y > 1) { d.y = 0; d.x = Math.random(); } if (d.x > 1) d.x -= 1; if (d.x < 0) d.x += 1;
      ctx.fillStyle = d.l > .9 ? 'rgba(255,150,90,.8)' : 'rgba(170,160,156,.6)'; ctx.fillRect(d.x * W, d.y * H, 2 * d.l, 2 * d.l);
    }
  }
  for (const p of run.ashes || []) {
    const a = Math.min(1, p.t / .6, (6 - p.t) / .6);
    const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r); g.addColorStop(0, `rgba(255,120,60,${.32 * a})`); g.addColorStop(1, 'rgba(255,120,60,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, 7); ctx.fill();
    if (!lowFx) { ctx.fillStyle = `rgba(255,190,120,${.8 * a})`; for (let i = 0; i < 6; i++) { const q = (time * .6 + i / 6) % 1; ctx.fillRect(p.x + Math.sin(i * 2.4) * p.r * .6, p.y - p.r * .6 + q * p.r * 1.2, 2, 2); } }
  }
  for (const f of run.fls || []) {
    const s = 26 * U * (1 + Math.sin(time * 3 + f.ph) * .15), g = glow('#d8ff9a');
    ctx.globalCompositeOperation = 'lighter'; ctx.drawImage(g, f.x - s, f.y - s, s * 2, s * 2); ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#f0ffe0'; ctx.beginPath(); ctx.arc(f.x, f.y + Math.sin(time * 2 + f.ph) * 3, 4 * U, 0, 7); ctx.fill();
  }
  if (run.rooted > 0) { // reeds wrapped around the lamp
    ctx.strokeStyle = 'rgba(111,143,106,.9)'; ctx.lineWidth = 3 * U; const L = G.lamp;
    for (let i = 0; i < 5; i++) { ctx.beginPath(); ctx.moveTo(L.x - 22 * U + i * 11 * U, L.y + 26 * U); ctx.quadraticCurveTo(L.x + Math.sin(time * 2 + i) * 18 * U, L.y, L.x - 18 * U + i * 9 * U, L.y - 20 * U); ctx.stroke(); }
  }
}
// Region backdrops (drawn once into the background layer)
function drawAshBackdrop(x, sy) {
  const id = curRegion().id;
  if (id === 'ashen') { // smoking cones with a red glow at the vents
    for (const [px, w, h] of [[.06, 70, 60], [.84, 90, 78]]) {
      const bx = W * px; x.fillStyle = '#1e1210'; x.beginPath(); x.moveTo(bx - w * U, sy); x.lineTo(bx - 8 * U, sy - h * U); x.lineTo(bx + 8 * U, sy - h * U); x.lineTo(bx + w * U, sy); x.fill();
      const g = x.createRadialGradient(bx, sy - h * U, 0, bx, sy - h * U, 40 * U); g.addColorStop(0, 'rgba(255,110,50,.5)'); g.addColorStop(1, 'rgba(255,110,50,0)'); x.fillStyle = g; x.fillRect(bx - 40 * U, sy - h * U - 40 * U, 80 * U, 80 * U);
    }
  } else if (id === 'marsh') { // reeds along the shore
    const R = mulberry32(31); x.strokeStyle = '#132418'; x.lineWidth = 2;
    for (let i = 0; i < 90; i++) { const px = R() * W, h = (20 + R() * 46) * U; if (px > W * .35 && px < W * .65) continue; x.beginPath(); x.moveTo(px, sy + 2); x.quadraticCurveTo(px + (R() - .5) * 10 * U, sy - h * .6, px + (R() - .5) * 14 * U, sy - h); x.stroke(); }
  }
}

/* ---- src\js\10e-scenery.js ---- */
/* =====================================================================
   SCENERY (0.14): each new region's backdrop is layered from cultural motifs (far, middle and near silhouettes in the
   region's palette), drawn once into the background. Plus festival decorations, and the live effects of the new
   region mechanics (rockslides, pools, gusts, dust, petals, mirages, aurora).
   Fictional places that remember many human cultures: shapes are inspired, never copied from real buildings.
   ===================================================================== */
const SCN = {
  // simple shapes, in the canvas x, at sea line sy
  tri(x, cx, base, w, h) { x.beginPath(); x.moveTo(cx - w / 2, base); x.lineTo(cx, base - h); x.lineTo(cx + w / 2, base); x.fill(); },
  box(x, l, base, w, h) { x.fillRect(l, base - h, w, h); },
  curvedRoof(x, cx, y, w, h) { x.beginPath(); x.moveTo(cx - w * .6, y); x.quadraticCurveTo(cx - w * .3, y - h * .2, cx, y - h); x.quadraticCurveTo(cx + w * .3, y - h * .2, cx + w * .6, y); x.lineTo(cx + w * .66, y - h * .18); x.lineTo(cx + w * .6, y); x.lineTo(cx - w * .6, y); x.lineTo(cx - w * .66, y - h * .18); x.closePath(); x.fill(); },
  dots(x, pts, col, s) { x.fillStyle = col; for (const [px, py] of pts) x.fillRect(px - s / 2, py - s / 2, s, s); },
};
const MOTIF = {
  mountains(x, sy, p, R) { x.fillStyle = p.hill2; for (let i = 0; i < 5; i++) SCN.tri(x, W * (i / 4) + R() * 40 * U, sy, W * .45, (60 + R() * 60) * U); },
  peaks(x, sy, p, R) { x.fillStyle = p.hill2; for (let i = 0; i < 6; i++) { const cx = W * i / 5 + (R() - .5) * 30 * U; SCN.tri(x, cx, sy, W * .28, (90 + R() * 80) * U); x.fillStyle = 'rgba(240,248,255,.35)'; SCN.tri(x, cx, sy - (60 + R() * 20) * U, W * .08, 30 * U); x.fillStyle = p.hill2; } },
  pines(x, sy, p, R) { x.fillStyle = p.hill; for (let i = 0; i < 26; i++) { const cx = R() * W; if (cx > W * .38 && cx < W * .62) continue; const h = (20 + R() * 26) * U; for (let k = 0; k < 3; k++) SCN.tri(x, cx, sy - k * h * .28, h * .55 * (1 - k * .2), h * .5); } },
  stonewall(x, sy, p) { x.fillStyle = p.hill; x.fillRect(0, sy - 10 * U, W * .34, 10 * U); x.fillRect(W * .66, sy - 10 * U, W * .34, 10 * U); x.fillStyle = 'rgba(0,0,0,.25)'; for (let i = 0; i < W; i += 14 * U) if (i < W * .34 || i > W * .66) x.fillRect(i, sy - 10 * U, 1, 10 * U); },
  tileroofs(x, sy, p, R) { for (const cx of [W * .1, W * .22, W * .8, W * .9]) { x.fillStyle = p.hill; SCN.box(x, cx - 14 * U, sy - 10 * U, 28 * U, 12 * U); x.fillStyle = p.hill2; SCN.curvedRoof(x, cx, sy - 22 * U, 32 * U, 12 * U); SCN.dots(x, [[cx, sy - 16 * U]], 'rgba(255,200,120,.7)', 3 * U); } },
  moongate(x, sy, p) { const cx = W * .84, cy = sy - 34 * U, r = 22 * U; x.fillStyle = p.hill; x.fillRect(cx - 32 * U, sy - 60 * U, 64 * U, 60 * U); x.globalCompositeOperation = 'destination-out'; x.beginPath(); x.arc(cx, cy, r, 0, 7); x.fill(); x.globalCompositeOperation = 'source-over'; },
  bamboo(x, sy, p, R) { x.strokeStyle = p.hill; x.lineWidth = 2 * U; for (let i = 0; i < 40; i++) { const cx = R() * W; if (cx > W * .36 && cx < W * .64) continue; const h = (40 + R() * 60) * U; x.beginPath(); x.moveTo(cx, sy); x.lineTo(cx + (R() - .5) * 8 * U, sy - h); x.stroke(); } },
  pagoda(x, sy, p) { const cx = W * .12; x.fillStyle = p.hill2; for (let t = 0; t < 5; t++) { const y = sy - 14 * U - t * 16 * U, w = (46 - t * 6) * U; SCN.box(x, cx - w * .3, y + 14 * U, w * .6, 14 * U); SCN.curvedRoof(x, cx, y, w, 9 * U); } x.fillRect(cx - 1 * U, sy - 104 * U, 2 * U, 16 * U); },
  lanternbridge(x, sy, p) { x.strokeStyle = p.hill; x.lineWidth = 4 * U; x.beginPath(); x.moveTo(W * .64, sy - 6 * U); x.quadraticCurveTo(W * .8, sy - 40 * U, W * .98, sy - 6 * U); x.stroke(); for (let i = 1; i < 8; i++) { const t = i / 8, bx = W * (.64 + .34 * t), by = sy - 6 * U - Math.sin(t * Math.PI) * 30 * U; SCN.dots(x, [[bx, by - 8 * U]], 'rgba(255,120,80,.85)', 4 * U); } },
  paperlanterns(x, sy, p, R) { for (let i = 0; i < 14; i++) { const lx = R() * W, ly = sy - (80 + R() * 160) * U; x.fillStyle = 'rgba(255,140,80,.18)'; x.beginPath(); x.arc(lx, ly, 9 * U, 0, 7); x.fill(); x.fillStyle = 'rgba(255,170,100,.8)'; x.fillRect(lx - 2.5 * U, ly - 3.5 * U, 5 * U, 7 * U); } },
  cedars(x, sy, p, R) { x.fillStyle = p.hill; for (let i = 0; i < 16; i++) { const cx = R() * W; if (cx > W * .38 && cx < W * .62) continue; const h = (34 + R() * 30) * U; for (let k = 0; k < 4; k++) x.fillRect(cx - (10 - k * 2) * U, sy - h + k * h * .22, (20 - k * 4) * U, h * .12); x.fillRect(cx - 1.5 * U, sy - h * .4, 3 * U, h * .4); } },
  shrinegate(x, sy, p) { const cx = W * .86, h = 44 * U; x.fillStyle = '#8a2a24'; x.fillRect(cx - 18 * U, sy - h, 4 * U, h); x.fillRect(cx + 14 * U, sy - h, 4 * U, h); x.fillRect(cx - 26 * U, sy - h - 3 * U, 52 * U, 5 * U); x.fillRect(cx - 20 * U, sy - h + 8 * U, 40 * U, 3 * U); },
  rockgarden(x, sy, p, R) { x.fillStyle = p.hill2; for (let i = 0; i < 6; i++) { const cx = R() * W; if (cx > W * .4 && cx < W * .6) continue; x.beginPath(); x.ellipse(cx, sy, (8 + R() * 14) * U, (6 + R() * 10) * U, 0, Math.PI, 0); x.fill(); } },
  palms(x, sy, p, R) { x.strokeStyle = p.hill; x.fillStyle = p.hill; for (let i = 0; i < 12; i++) { const cx = R() * W; if (cx > W * .36 && cx < W * .64) continue; const h = (40 + R() * 36) * U, lean = (R() - .5) * 20 * U; x.lineWidth = 3 * U; x.beginPath(); x.moveTo(cx, sy); x.quadraticCurveTo(cx + lean * .3, sy - h * .6, cx + lean, sy - h); x.stroke();
    for (let k = 0; k < 6; k++) { const a = k / 6 * Math.PI * 2; x.beginPath(); x.moveTo(cx + lean, sy - h); x.quadraticCurveTo(cx + lean + Math.cos(a) * 14 * U, sy - h - 6 * U, cx + lean + Math.cos(a) * 22 * U, sy - h + Math.abs(Math.sin(a)) * 12 * U); x.lineWidth = 2 * U; x.stroke(); } } },
  stilthouses(x, sy, p) { for (const cx of [W * .1, W * .88]) { x.fillStyle = p.hill; for (const dx of [-12, -4, 4, 12]) x.fillRect(cx + dx * U, sy - 14 * U, 1.5 * U, 16 * U); x.fillRect(cx - 16 * U, sy - 26 * U, 32 * U, 12 * U); SCN.tri(x, cx, sy - 26 * U, 44 * U, 18 * U); SCN.dots(x, [[cx, sy - 20 * U]], 'rgba(255,200,120,.75)', 3 * U); } },
  terraces(x, sy, p) { x.fillStyle = p.hill2; for (let k = 0; k < 6; k++) x.fillRect(W * (.62 + k * .04), sy - (k + 1) * 10 * U, W, 10 * U); x.fillStyle = 'rgba(120,200,120,.18)'; for (let k = 0; k < 6; k++) x.fillRect(W * (.62 + k * .04), sy - (k + 1) * 10 * U, W, 2 * U); },
  outriggers(x, sy, p) { for (const cx of [W * .28, W * .72]) { x.fillStyle = p.hill; x.beginPath(); x.ellipse(cx, sy + 3 * U, 16 * U, 3 * U, 0, 0, 7); x.fill(); x.fillRect(cx - 18 * U, sy - 1 * U, 36 * U, 1.2 * U); x.fillRect(cx - 1 * U, sy - 24 * U, 2 * U, 24 * U); SCN.tri(x, cx + 7 * U, sy - 4 * U, 14 * U, 20 * U); } },
  grassland(x, sy, p) { x.fillStyle = p.hill2; x.beginPath(); x.moveTo(0, sy); x.quadraticCurveTo(W * .3, sy - 22 * U, W * .6, sy - 8 * U); x.quadraticCurveTo(W * .8, sy - 2 * U, W, sy - 14 * U); x.lineTo(W, sy); x.fill(); },
  tents(x, sy, p) { for (const cx of [W * .12, W * .2, W * .84]) { x.fillStyle = '#e8dcc0'; x.beginPath(); x.moveTo(cx - 12 * U, sy); x.lineTo(cx - 12 * U, sy - 10 * U); x.quadraticCurveTo(cx, sy - 20 * U, cx + 12 * U, sy - 10 * U); x.lineTo(cx + 12 * U, sy); x.fill(); x.fillStyle = 'rgba(160,80,40,.6)'; x.fillRect(cx - 12 * U, sy - 9 * U, 24 * U, 2 * U); } },
  standingstones(x, sy, p) { x.fillStyle = p.hill; for (let i = 0; i < 6; i++) { const cx = W * (.66 + i * .05); x.fillRect(cx, sy - (16 + (i % 3) * 6) * U, 6 * U, (16 + (i % 3) * 6) * U); } },
  blossomtrees(x, sy, p, R) { for (let i = 0; i < 12; i++) { const cx = R() * W; if (cx > W * .36 && cx < W * .64) continue; x.fillStyle = p.hill; x.fillRect(cx - 2 * U, sy - 22 * U, 4 * U, 22 * U); x.fillStyle = 'rgba(255,170,200,.8)'; for (let k = 0; k < 5; k++) { x.beginPath(); x.arc(cx + (R() - .5) * 26 * U, sy - (26 + R() * 14) * U, (8 + R() * 6) * U, 0, 7); x.fill(); } } },
  castle(x, sy, p) { const cx = W * .12; x.fillStyle = p.hill; x.fillRect(cx - 30 * U, sy - 20 * U, 60 * U, 20 * U); x.fillStyle = p.hill2; for (let t = 0; t < 3; t++) { const y = sy - 20 * U - t * 14 * U, w = (54 - t * 12) * U; x.fillRect(cx - w * .35, y - 12 * U, w * .7, 12 * U); SCN.curvedRoof(x, cx, y - 12 * U, w, 7 * U); } },
  temples(x, sy, p) { for (const [cx, hy] of [[W * .1, 60], [W * .9, 80]]) { x.fillStyle = p.hill; x.fillRect(cx - 14 * U, sy - hy * U, 28 * U, 14 * U); x.fillStyle = '#c8a040'; SCN.curvedRoof(x, cx, sy - hy * U, 36 * U, 10 * U); x.strokeStyle = p.hill; x.lineWidth = 1.5 * U; x.beginPath(); x.moveTo(cx, sy - hy * U + 14 * U); x.lineTo(cx, sy); x.stroke(); } },
  clouds(x, sy, p, R) { x.fillStyle = 'rgba(230,236,255,.14)'; for (let i = 0; i < 8; i++) { const cx = R() * W, cy = sy - (40 + R() * 120) * U; for (let k = 0; k < 4; k++) { x.beginPath(); x.ellipse(cx + k * 16 * U, cy + (k % 2) * 4 * U, 22 * U, 9 * U, 0, 0, 7); x.fill(); } } },
  flags(x, sy, p) { const cols = ['#e84a4a', '#ffd84a', '#4ae07a', '#4a8ae8', '#f0f0f0']; for (let i = 0; i < 12; i++) { x.fillStyle = cols[i % 5]; x.fillRect(W * (.66 + i * .025), sy - 40 * U + Math.sin(i) * 3 * U, 5 * U, 4 * U); } },
  walls(x, sy, p) { x.fillStyle = p.hill; x.fillRect(0, sy - 18 * U, W * .36, 18 * U); x.fillRect(W * .64, sy - 18 * U, W * .36, 18 * U); for (let i = 0; i < W; i += 10 * U) if (i < W * .36 || i > W * .64) x.fillRect(i, sy - 22 * U, 5 * U, 4 * U); },
  palace(x, sy, p) { const cx = W * .86; x.fillStyle = p.hill2; x.fillRect(cx - 34 * U, sy - 30 * U, 68 * U, 30 * U); SCN.curvedRoof(x, cx, sy - 30 * U, 80 * U, 14 * U); SCN.curvedRoof(x, cx, sy - 46 * U, 50 * U, 12 * U); SCN.dots(x, [[cx - 16 * U, sy - 16 * U], [cx, sy - 16 * U], [cx + 16 * U, sy - 16 * U]], 'rgba(255,140,60,.8)', 4 * U); },
  chimneys(x, sy, p) { for (const cx of [W * .08, W * .18, W * .28, W * .74]) { x.fillStyle = p.hill; x.fillRect(cx, sy - 50 * U, 7 * U, 50 * U); x.fillStyle = 'rgba(255,120,60,.5)'; x.fillRect(cx, sy - 52 * U, 7 * U, 3 * U); } },
  forgeglow(x, sy) { const g = x.createRadialGradient(W / 2, sy, 0, W / 2, sy, W * .6); g.addColorStop(0, 'rgba(255,100,40,.22)'); g.addColorStop(1, 'rgba(255,100,40,0)'); x.fillStyle = g; x.fillRect(0, sy - W * .6, W, W * .6); },
  whitevillage(x, sy, p, R) { for (let i = 0; i < 12; i++) { const cx = R() * W; if (cx > W * .36 && cx < W * .64) continue; const w = (14 + R() * 14) * U, h = (10 + R() * 12) * U, base = sy - R() * 20 * U; x.fillStyle = '#e8e4dc'; x.fillRect(cx, base - h, w, h); x.fillStyle = '#b8603a'; x.fillRect(cx - 2 * U, base - h - 3 * U, w + 4 * U, 3 * U); x.fillStyle = 'rgba(40,60,120,.7)'; x.fillRect(cx + w * .4, base - h * .6, 3 * U, 4 * U); } },
  belltower(x, sy, p) { const cx = W * .9; x.fillStyle = '#e8e4dc'; x.fillRect(cx - 8 * U, sy - 70 * U, 16 * U, 70 * U); x.fillStyle = '#b8603a'; SCN.tri(x, cx, sy - 70 * U, 22 * U, 16 * U); x.fillStyle = '#2a2a3a'; x.beginPath(); x.arc(cx, sy - 58 * U, 4 * U, Math.PI, 0); x.fill(); x.fillRect(cx - 4 * U, sy - 58 * U, 8 * U, 5 * U); },
  seafort(x, sy, p) { x.fillStyle = p.hill2; x.fillRect(0, sy - 26 * U, W * .2, 26 * U); for (let i = 0; i < W * .2; i += 9 * U) x.fillRect(i, sy - 31 * U, 5 * U, 5 * U); x.fillStyle = '#2a2a3a'; x.fillRect(W * .2, sy - 16 * U, 10 * U, 3 * U); },
  cypress(x, sy, p, R) { x.fillStyle = p.hill; for (let i = 0; i < 8; i++) { const cx = W * (.62 + R() * .36), h = (30 + R() * 20) * U; x.beginPath(); x.ellipse(cx, sy - h / 2, 4 * U, h / 2, 0, 0, 7); x.fill(); } },
  docks(x, sy, p) { x.fillStyle = p.hill; x.fillRect(W * .66, sy - 4 * U, W * .34, 4 * U); for (let i = 0; i < 8; i++) x.fillRect(W * (.67 + i * .04), sy - 4 * U, 2 * U, 10 * U); x.fillRect(W * .9, sy - 22 * U, 2 * U, 18 * U); x.fillRect(W * .86, sy - 20 * U, 10 * U, 2 * U); },
  lighthousetown(x, sy, p) { for (const [cx, w, h] of [[W * .06, 16, 14], [W * .14, 20, 18], [W * .23, 14, 12]]) { x.fillStyle = p.hill2; x.fillRect(cx, sy - h * U, w * U, h * U); SCN.tri(x, cx + w * U / 2, sy - h * U, (w + 4) * U, 8 * U); SCN.dots(x, [[cx + w * U / 2, sy - h * U * .5]], 'rgba(255,210,140,.8)', 3 * U); } const cx = W * .3; x.fillStyle = '#e8e4dc'; x.fillRect(cx, sy - 44 * U, 7 * U, 44 * U); SCN.dots(x, [[cx + 3.5 * U, sy - 47 * U]], '#fff0b0', 5 * U); },
  railway(x, sy, p) { x.fillStyle = p.hill; x.fillRect(0, sy - 16 * U, W * .34, 3 * U); for (let i = 0; i < W * .34; i += 12 * U) x.fillRect(i, sy - 16 * U, 2 * U, 16 * U); x.fillStyle = p.hill2; x.fillRect(W * .04, sy - 30 * U, 30 * U, 14 * U); x.fillRect(W * .04 + 22 * U, sy - 40 * U, 5 * U, 10 * U); },
  dunes(x, sy, p) { x.fillStyle = p.hill2; x.beginPath(); x.moveTo(0, sy); for (let i = 0; i <= 8; i++) x.quadraticCurveTo(W * (i - .5) / 8, sy - (20 + (i % 3) * 12) * U, W * i / 8, sy - (i % 2) * 6 * U); x.lineTo(W, sy); x.fill(); },
  domes(x, sy, p) { for (const [cx, r] of [[W * .1, 18], [W * .2, 12], [W * .86, 22]]) { x.fillStyle = p.hill; x.fillRect(cx - r * U, sy - r * 1.2 * U, r * 2 * U, r * 1.2 * U); x.beginPath(); x.arc(cx, sy - r * 1.2 * U, r * U, Math.PI, 0); x.fill(); } },
  ruins(x, sy, p, R) { x.fillStyle = p.hill; for (let i = 0; i < 7; i++) { const cx = W * (.64 + i * .05); x.fillRect(cx, sy - (10 + R() * 26) * U, 5 * U, 40 * U); } },
  mesas(x, sy, p, R) { x.fillStyle = p.hill2; for (const [cx, w, h] of [[W * .08, 90, 60], [W * .3, 60, 40], [W * .78, 110, 70]]) { x.beginPath(); x.moveTo(cx - w * U / 2, sy); x.lineTo(cx - w * U / 2 + 10 * U, sy - h * U); x.lineTo(cx + w * U / 2 - 10 * U, sy - h * U); x.lineTo(cx + w * U / 2, sy); x.fill(); } },
  arches(x, sy, p) { const cx = W * .86; x.fillStyle = p.hill; x.fillRect(cx - 34 * U, sy - 44 * U, 68 * U, 44 * U); x.globalCompositeOperation = 'destination-out'; x.beginPath(); x.ellipse(cx, sy, 22 * U, 30 * U, 0, Math.PI, 0); x.fill(); x.globalCompositeOperation = 'source-over'; },
  canyonwalls(x, sy, p) { x.fillStyle = p.hill; x.beginPath(); x.moveTo(0, sy); x.lineTo(0, sy - 90 * U); x.lineTo(W * .14, sy - 70 * U); x.lineTo(W * .2, sy); x.fill(); x.beginPath(); x.moveTo(W, sy); x.lineTo(W, sy - 100 * U); x.lineTo(W * .84, sy - 76 * U); x.lineTo(W * .8, sy); x.fill(); },
  crater(x, sy, p) { x.fillStyle = p.hill2; x.beginPath(); x.moveTo(0, sy); x.quadraticCurveTo(W * .15, sy - 50 * U, W * .3, sy - 10 * U); x.lineTo(W * .7, sy - 10 * U); x.quadraticCurveTo(W * .85, sy - 50 * U, W, sy); x.fill(); },
  meteors(x, sy, p, R) { x.strokeStyle = 'rgba(255,240,180,.5)'; x.lineWidth = 1.5; for (let i = 0; i < 6; i++) { const mx = R() * W, my = R() * sy * .6; x.beginPath(); x.moveTo(mx, my); x.lineTo(mx - 30 * U, my - 16 * U); x.stroke(); } },
  starfield(x, sy, p, R) { for (let i = 0; i < 160; i++) { x.fillStyle = `rgba(230,236,255,${.2 + R() * .6})`; const s = R() < .1 ? 2 : 1; x.fillRect(R() * W, R() * sy * .9, s, s); } },
  wrecks(x, sy, p, R) { x.strokeStyle = p.hill; x.lineWidth = 2 * U; for (let i = 0; i < 7; i++) { const cx = R() * W; if (cx > W * .38 && cx < W * .62) continue; const h = (24 + R() * 30) * U, lean = (R() - .5) * .5; x.beginPath(); x.moveTo(cx, sy); x.lineTo(cx + lean * h, sy - h); x.stroke(); x.beginPath(); x.moveTo(cx + lean * h * .6 - 8 * U, sy - h * .6); x.lineTo(cx + lean * h * .6 + 8 * U, sy - h * .6); x.stroke(); } },
  floatingisles(x, sy, p, R) { for (let i = 0; i < 4; i++) { const cx = R() * W, cy = sy - (80 + R() * 120) * U, w = (30 + R() * 30) * U; x.fillStyle = 'rgba(160,200,220,.18)'; x.beginPath(); x.moveTo(cx - w, cy); x.lineTo(cx + w, cy); x.lineTo(cx, cy + w * .8); x.fill(); } },
  ghostships(x, sy, p) { x.fillStyle = 'rgba(180,220,235,.18)'; for (const cx of [W * .16, W * .82]) { x.beginPath(); x.moveTo(cx - 24 * U, sy - 10 * U); x.lineTo(cx + 24 * U, sy - 10 * U); x.lineTo(cx + 16 * U, sy); x.lineTo(cx - 16 * U, sy); x.fill(); x.fillRect(cx - 1 * U, sy - 50 * U, 2 * U, 40 * U); SCN.tri(x, cx + 10 * U, sy - 14 * U, 20 * U, 30 * U); } },
  spires(x, sy, p, R) { x.fillStyle = p.hill2; for (let i = 0; i < 12; i++) { const cx = R() * W; if (cx > W * .38 && cx < W * .62) continue; SCN.tri(x, cx, sy, (8 + R() * 10) * U, (50 + R() * 80) * U); } },
  citywall(x, sy, p) { MOTIF.walls(x, sy, p); },
  glassshards(x, sy, p, R) { x.fillStyle = 'rgba(200,170,255,.18)'; for (let i = 0; i < 16; i++) { const cx = R() * W; SCN.tri(x, cx, sy, 6 * U, (8 + R() * 16) * U); } },
  icefields(x, sy, p) { x.fillStyle = p.hill; x.fillRect(0, sy - 8 * U, W, 8 * U); x.fillStyle = 'rgba(255,255,255,.4)'; x.fillRect(0, sy - 8 * U, W, 1.5 * U); },
  aurora(x, sy, p) { for (let k = 0; k < 3; k++) { const g = x.createLinearGradient(0, sy * .1, 0, sy * .5); g.addColorStop(0, 'rgba(120,255,190,0)'); g.addColorStop(.5, `rgba(120,255,190,${.12 - k * .03})`); g.addColorStop(1, 'rgba(160,120,255,0)'); x.fillStyle = g; x.beginPath(); x.moveTo(0, sy * (.2 + k * .06)); for (let i = 0; i <= 10; i++) x.lineTo(W * i / 10, sy * (.18 + k * .06) + Math.sin(i * 1.3 + k) * 24 * U); x.lineTo(W, sy * .55); x.lineTo(0, sy * .55); x.fill(); } },
  iceberg(x, sy, p) { x.fillStyle = '#e8f4ff'; for (const [cx, w, h] of [[W * .12, 60, 40], [W * .86, 80, 56]]) { x.beginPath(); x.moveTo(cx - w * U / 2, sy); x.lineTo(cx - w * U / 5, sy - h * U); x.lineTo(cx + w * U / 6, sy - h * .7 * U); x.lineTo(cx + w * U / 2, sy); x.fill(); } },
  waterfall(x, sy, p) { const g = x.createLinearGradient(0, sy - 8 * U, 0, sy + 30 * U); g.addColorStop(0, 'rgba(160,190,255,.35)'); g.addColorStop(1, 'rgba(160,190,255,0)'); x.fillStyle = g; x.fillRect(0, sy - 2 * U, W, 30 * U); x.fillStyle = 'rgba(230,236,255,.5)'; x.fillRect(0, sy - 2 * U, W, 1.5 * U); },
  cliffs(x, sy, p) { x.fillStyle = p.hill; x.beginPath(); x.moveTo(0, sy); x.lineTo(0, sy - 70 * U); x.lineTo(W * .1, sy - 60 * U); x.lineTo(W * .16, sy); x.fill(); x.beginPath(); x.moveTo(W, sy); x.lineTo(W, sy - 80 * U); x.lineTo(W * .9, sy - 70 * U); x.lineTo(W * .85, sy); x.fill(); },
  firsttower(x, sy, p) { const cx = W * .5, top = sy * .12; const g = x.createLinearGradient(cx, top, cx, sy); g.addColorStop(0, 'rgba(255,250,220,.1)'); g.addColorStop(1, 'rgba(255,250,220,.02)'); x.fillStyle = g; x.beginPath(); x.moveTo(cx - 20 * U, sy); x.lineTo(cx - 8 * U, top); x.lineTo(cx + 8 * U, top); x.lineTo(cx + 20 * U, sy); x.fill();
    const lg = x.createRadialGradient(cx, top, 0, cx, top, 90 * U); lg.addColorStop(0, 'rgba(255,250,220,.35)'); lg.addColorStop(1, 'rgba(255,250,220,0)'); x.fillStyle = lg; x.fillRect(cx - 90 * U, top - 90 * U, 180 * U, 180 * U); },
  rays(x, sy) { x.fillStyle = 'rgba(255,250,220,.04)'; for (let i = 0; i < 6; i++) { x.beginPath(); x.moveTo(W * .5, sy * .12); x.lineTo(W * (i / 5) - 40 * U, sy); x.lineTo(W * (i / 5) + 40 * U, sy); x.fill(); } },
};
// the new regions' backdrops (called while the background layer is built)
function drawWorldBackdrop(x, sy) {
  const r = curRegion(), sc = r.scene; if (!sc) { drawFestivalBackdrop(x, sy); return; }
  const R = mulberry32(r.id.length * 977 + r.num.length);
  if (sc.moon === 'big' || sc.moon === 'red') { const mx = G.moon.x, my = G.moon.y, g = x.createRadialGradient(mx, my, 10 * U, mx, my, 90 * U); g.addColorStop(0, sc.moon === 'red' ? 'rgba(255,120,80,.25)' : 'rgba(230,236,255,.2)'); g.addColorStop(1, 'rgba(0,0,0,0)'); x.fillStyle = g; x.fillRect(mx - 90 * U, my - 90 * U, 180 * U, 180 * U); }
  for (const m of sc.motifs) if (MOTIF[m]) { x.save(); try { MOTIF[m](x, sy, r.pal, R); } catch (e) { /* a motif that doesn't fit this screen is skipped */ } x.restore(); }
  drawFestivalBackdrop(x, sy);
}
// festival scenery (static part)
function drawFestivalBackdrop(x, sy) {
  const f = activeFestival(); if (!f) return;
  const R = mulberry32(99);
  if (f.deco === 'lanterns') MOTIF.paperlanterns(x, sy, curRegion().pal, R);
  else if (f.deco === 'moon') { const mx = G.moon.x, my = G.moon.y, g = x.createRadialGradient(mx, my, 10 * U, mx, my, 120 * U); g.addColorStop(0, 'rgba(255,240,200,.35)'); g.addColorStop(1, 'rgba(255,240,200,0)'); x.fillStyle = g; x.fillRect(mx - 120 * U, my - 120 * U, 240 * U, 240 * U); }
  else if (f.deco === 'flowers') { for (let i = 0; i < 40; i++) SCN.dots(x, [[R() * W, sy + R() * (H - sy) * .6]], ['#ff9ab8', '#ffd84a', '#ffffff'][i % 3], 3 * U); }
  else if (f.deco === 'leaves') { for (let i = 0; i < 50; i++) SCN.dots(x, [[R() * W, R() * sy]], ['#d8782a', '#c8a02a', '#a84a2a'][i % 3], 2.5 * U); }
  else if (f.deco === 'snowlights') { x.strokeStyle = 'rgba(255,255,255,.2)'; x.lineWidth = 1; x.beginPath(); x.moveTo(0, sy * .2); x.quadraticCurveTo(W / 2, sy * .32, W, sy * .2); x.stroke(); for (let i = 0; i <= 20; i++) { const t = i / 20; SCN.dots(x, [[W * t, sy * .2 + Math.sin(t * Math.PI) * sy * .12]], ['#ff6a6a', '#6aff9a', '#6ab8ff', '#ffd86a'][i % 4], 3 * U); } }
}
// live effects of the region mechanics and festivals
function drawWorldEffects(dt) {
  if (!run) return;
  const S = run.wm, M = worldMech(), f = activeFestival();
  if (f && f.deco === 'fireworks' && !reduceMotion && !lowFx && mode === 'play' && Math.random() < dt * .8) { const fx = rnd(W * .15, W * .85), fy = rnd(H * .08, H * .3); /* drawing never touches the seeded rr(): replays must match */ for (let i = 0; i < 18; i++) { const a = i / 18 * 6.283; P(1, fx, fy, Math.cos(a) * 120 * U, Math.sin(a) * 120 * U, .9, ['#ffd86a', '#ff6a8a', '#8ad8ff'][i % 3], 0); } }
  if (!S) return;
  if (S.slide) { const x0 = S.slide.x0, w = S.slide.x1 - x0, a = .25 + .25 * Math.sin(time * 12); ctx.fillStyle = `rgba(200,140,110,${a})`; ctx.fillRect(x0, 0, w, G.tt - 40 * U); }
  for (const p of S.pools || []) { const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r); g.addColorStop(0, 'rgba(120,190,220,.28)'); g.addColorStop(1, 'rgba(120,190,220,0)'); ctx.fillStyle = g; ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, 7); ctx.fill(); }
  if (S.gust > 0 && !lowFx) { ctx.strokeStyle = 'rgba(220,240,230,.25)'; ctx.lineWidth = 1.5; for (let i = 0; i < 12; i++) { const y = (i * 97 + time * 60) % H, x0 = (time * 400 * S.gustDir + i * 150) % W; ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(x0 + 40 * S.gustDir * U, y); ctx.stroke(); } }
  if (S.dust > 0 && run.squall > 0) { ctx.fillStyle = `rgba(210,180,120,${Math.min(.35, S.dust / 2)})`; ctx.fillRect(0, 0, W, H); }
  if (M === 'petals' && S.petal > 0 && !lowFx) { for (let i = 0; i < 30; i++) SCN.dots(ctx, [[(i * 131 + time * 50) % W, (i * 71 + time * 40) % H]], 'rgba(255,190,215,.8)', 3 * U); }
  if (M === 'aurora' && S.pulse > 0) { ctx.fillStyle = `rgba(120,255,190,${.08 + .05 * Math.sin(time * 4)})`; ctx.fillRect(0, 0, W, H * .5); }
  if (M === 'moonphase' && S.moon !== undefined) { ctx.fillStyle = 'rgba(230,236,255,.85)'; ctx.textAlign = 'center'; cfont(12, .9); ctx.fillText(S.moon > .5 ? 'Full moon: creatures stronger' : S.moon < -.5 ? 'New moon: creatures weaker' : '', W / 2, (G.hudB || 60) + 40 * Math.max(.9, U)); }
  for (const m of S.mirages || []) { ctx.globalAlpha = .45 + .15 * Math.sin(time * 5 + m.ph); ctx.fillStyle = '#9ad8ff'; ctx.beginPath(); ctx.ellipse(m.x, m.y, 12 * U, 11 * U, 0, 0, 7); ctx.fill(); ctx.globalAlpha = 1; }
}

