function openPadMap(onConnect, cfgIn) {
  const cfg = cfgIn || inputCfg(), fam = cfg.prompts && cfg.prompts !== 'auto' ? cfg.prompts : Input.family, names = PAD_NAMES[fam] || PAD_NAMES.xbox;
  const pad = Input.connected().find(p => p.family === fam) || Input.connected()[0];
  const rows = []; for (let b = 0; b <= 16; b++) { const acts = ACTION_IDS.filter(a => (cfg.pad[a] || []).includes(b)); if (acts.length) rows.push([names[b] || 'Button ' + b, acts.map(a => b === 0 && a === 'CONFIRM' ? 'Confirm (Strike in a night)' : ACTIONS[a]).join(', ')]); }
  rows.push([fam === 'nintendo' ? 'Left stick' : 'Left stick', 'Move between buttons in menus; aim in a night']); rows.push(['Right stick', 'Aim in a night; scroll in menus']);
  padMapBack = document.activeElement;
  const box = $('#padMap');
  box.innerHTML = `<div class="pmBox" role="dialog" aria-modal="true" aria-labelledby="pmT"><b id="pmT">${onConnect ? esc((pad ? pad.name : PAD_FAMILY_NAME[fam]) + ' connected') : 'Controller map'}</b>
    <p class="sub">${onConnect ? 'The buttons on screen are named for it now. Here is what each one does:' : 'What each button does right now (change them in Settings > Controls):'}</p>
    ${padMapSvg(fam, cfg)}<dl class="pmList">${rows.map(([k, v]) => `<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>
    <p class="sub">${esc(names[9])} pauses a night and shows this map again. Keyboard and touch keep working at the same time.</p>
    <div class="pmBtns">${onConnect ? '<button class="btn ghost" id="pmNever">Don\'t show this again</button>' : ''}<button class="btn primary" id="pmOk">Got it</button></div></div>`;
  box.hidden = false;
  $('#pmOk').onclick = () => closePadMap();
  if ($('#pmNever')) $('#pmNever').onclick = () => { const c = inputCfg(); c.mapOnConnect = false; save(); closePadMap(); toastQ.push(['Controls map', 'It stays in Pause and Settings > Controls.', 3]); };
  navFocus($('#pmOk'));
}
function closePadMap() { const box = $('#padMap'); box.hidden = true; box.innerHTML = ''; if (padMapBack && padMapBack.isConnected) padMapBack.focus({ preventScroll: true }); padMapBack = null; }

/* ---- src\js\11c-lifecycle.js ---- */
/* =====================================================================
   ACTIVE / AWAY (0.29): one place decides whether the player is in the game, the same on every platform.
   Active   = the game is in front: the screen stays awake (Wake Lock here; Android, iOS and the desktop app also keep
              the screen on natively while the game is in front), sound plays, everything runs.
   Away     = the page is hidden, the app went to the background (Home, another app, the lock screen, minimised,
              closing), or, on a computer, another app has the focus. Then: a single-player night pauses, the game
              saves, the audio engine is suspended (music, effects, ambience and loops stop at once), the main loop and
              the Bazaar stop drawing, background polling waits, and the screen may sleep.
   Online matches (PvP, co-op with partners) can't be frozen for the other player: they keep their connection and
   their clock, but stop drawing and sounding like everything else, and the existing reconnect rules apply.
   Coming back: audio resumes as it was, the frame clock restarts (no huge first step), away time is credited once
   (checkAway), and every timer is the one that was there: nothing is started twice.
   ===================================================================== */
const Life = {
  active: true, hidden: false, focused: true, wake: null, audioWas: '', since: 0, log: [], frames: 0,
  // live with other people: a co-op room (even one still waiting for partners), PvP from the search on, a duel request
  // waiting for an answer. Those keep running (and connected) while the player is away, but go quiet like everything else.
  online: () => !!((typeof Coop !== 'undefined' && Coop.role) || (typeof PVP !== 'undefined' && ((PVP.on && PVP.on()) || PVP.phase === 'search')) || (typeof Duel !== 'undefined' && (Duel.out || Duel.inc))),
  // on a computer, another app having the focus counts as away; on phones and tablets only visibility counts
  // (the on-screen keyboard and system sheets move the focus without the player leaving)
  focusMatters: () => Platform.kind === 'desktop' || (Platform.kind === 'web' && !!window.matchMedia && matchMedia('(pointer: fine)').matches && !matchMedia('(pointer: coarse)').matches),
  check(why) {
    this.hidden = document.visibilityState === 'hidden';
    const now = !this.hidden && (!this.focusMatters() || document.hasFocus() || this.focused);
    if (now !== this.active) this.set(now, why);
  },
  set(active, why) {
    this.active = active; this.since = performance.now(); this.log.push([Date.now(), active ? 'active' : 'away', why]); if (this.log.length > 40) this.log.shift();
    if (active) this.resume(); else this.pause();
  },
  pause() {
    // the night: a single-player night pauses; a hidden page pauses any night it may (as before 0.29)
    if (typeof run !== 'undefined' && run && mode === 'play' && (this.hidden || !this.online())) Cmd.dispatch({ t: 'PAUSE' });
    try { syncRunHp(); meta.last = Date.now(); save(); } catch (e) { /* saved on the next change */ }
    // sound: the whole audio engine stops (and frees its thread) until the player is back
    if (Sfx.c && Sfx.c.state === 'running') { this.audioWas = 'running'; Sfx.c.suspend().catch(() => {}); } else this.audioWas = Sfx.c ? Sfx.c.state : '';
    // the Bazaar's 3D street stops drawing
    if (typeof Bazaar !== 'undefined' && Bazaar.on) cancelAnimationFrame(Bazaar.raf);
    this.unwake();
  },
  resume() {
    lastT = performance.now(); // the first frame back is a normal one
    if (Sfx.c && this.audioWas === 'running' && Sfx.c.state === 'suspended') Sfx.c.resume().catch(() => {});
    this.audioWas = '';
    if (typeof Bazaar !== 'undefined' && Bazaar.on) { cancelAnimationFrame(Bazaar.raf); Bazaar.last = performance.now(); Bazaar.raf = requestAnimationFrame(bzFrame); }
    try { checkAway(true); } catch (e) { /* home screen not ready */ }
    this.keepAwake();
  },
  // the screen stays awake while the game is in front (browsers and the web app; the apps do it natively too)
  async keepAwake() {
    if (!this.active || this.wake || !navigator.wakeLock || !navigator.wakeLock.request) return;
    try { this.wake = await navigator.wakeLock.request('screen'); this.wake.addEventListener('release', () => { this.wake = null; }); } catch (e) { this.wake = null; } // (refused: battery saver, a policy)
    if (!this.active) this.unwake(); // left while asking
  },
  unwake() { const w = this.wake; this.wake = null; if (w) w.release().catch(() => {}); },
};
document.addEventListener('visibilitychange', () => Life.check('visibility'));
window.addEventListener('blur', () => { Life.focused = false; setTimeout(() => Life.check('blur'), 0); });
window.addEventListener('focus', () => { Life.focused = true; Life.check('focus'); });
window.addEventListener('pagehide', () => { Life.check('pagehide'); try { syncRunHp(); save(); } catch (e) { /* closing */ } });
// the apps: Capacitor reports the app going to the background and back (Home, another app, the lock screen)
try { const A = window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.App; if (A && A.addListener) A.addListener('appStateChange', s => { Life.focused = !!s.isActive; if (!s.isActive) { if (Life.active) Life.set(false, 'app background'); } else Life.check('app foreground'); }); } catch (e) { /* the web */ }
// the first touch or click also asks for the wake lock (some browsers want a gesture)
window.addEventListener('pointerdown', () => { if (Life.active && !Life.wake) Life.keepAwake(); }, { passive: true });
Life.keepAwake();

/* ---- src\js\12-loop.js ---- */
/* =====================================================================
   LOOP  (fixed 60 Hz simulation steps, so 3× speed stays accurate)
   ===================================================================== */
const STEP = 1 / 60;
let lastT = performance.now(), acc = 0, saveT = 0, uiT = 0, perfT = 0, perfN = 0;
// 0.28: a co-op server's copy of the game (index.html#lkserver=..., server/lite-host.js) only simulates: it draws
// nothing, plays nothing, refreshes its (unseen) screen once a second, and runs the loop 30 times a second instead of
// every frame. The simulation keeps its fixed 60 Hz steps (two per call), and snapshots still go out 15 times a second.
// That is what lets one small free server run several nights.
const SERVER_PAGE = /lkserver=/.test(location.hash);
const nextFrame = () => { if (SERVER_PAGE) setTimeout(() => loop(performance.now()), CoopServer.pending ? 500 : 1000 / 30); else requestAnimationFrame(loop); }; // (a spare waiting for a room ticks twice a second)
function loop(now) {
  // 0.29: away (another app, the background, the lock screen) and no online match running: nothing to draw; look
  // again four times a second until the player is back (Life.resume restarts the clock)
  if (!Life.active && !SERVER_PAGE && !Life.online()) { lastT = now; setTimeout(nextFrame, 250); return; }
  Life.frames++; // (frames drawn: the lifecycle test counts them)
  if (fpsCap && now - frameAt < 1000 / fpsCap - 1.5) { nextFrame(); return; } // 0.25: a frame rate limit
  frameAt = now; fpsTick(now);
  let rdt = (now - lastT) / 1000; lastT = now;
  if (!(rdt > 0)) rdt = 0;
  const rawDt = rdt; rdt = Math.min(rdt, .1);
  time += rdt;
  if (!Replay.on) earn(stillRate() * rdt / 60, false);
  if (Replay.on) Replay.pump(rdt);
  Coop.tickHost(rdt); Coop.tickClient(rdt); coopVoteTick(rdt); PVP.tick(rdt); pvpBreakTick(rdt);
  if (run && mode === 'play' && Net.mode !== 'client') {
    acc += rdt * speed; let n = 0;
    while (acc >= STEP && n < 14 && mode === 'play') { if (Replay.on) Replay.pump(0); if (mode !== 'play') break; update(STEP); acc -= STEP; n++; }
    if (n >= 14) acc = 0;
  } else acc = 0;
  fx(rdt * (mode === 'play' ? speed : 1));
  if (Net.mode === 'client' && run) run.hurt = Math.max(0, run.hurt);
  if (!SERVER_PAGE) draw(rdt);
  saveT += rdt; if (saveT > 5) { saveT = 0; syncRunHp(); save(); }
  uiT += rdt; if (uiT > (SERVER_PAGE ? 1 : .1)) { uiT = 0; refreshUI(); if (!Replay.on) checkAch(); }
  tickToast(rdt);
  tickCoopUi(rdt); // 0.14 co-op panels
  if (!SERVER_PAGE) { ambTick(rdt); Music.update(rdt); Music.tick(); } // 0.19: the context (menu, shop, a region, PvP...) picks the track; changes crossfade
  // Adaptive resolution: most cost is fill-rate at high pixel density, so slow devices render at a lower scale.
  // Step 1: lower render scale (very slow frames jump straight to 1x). Step 2: switch off costly ambient effects.
  // Gaps over half a second are tab switches or sleep, not slowness, so they're ignored.
  if (meta.settings.gfx === 'auto' && !document.hidden && rawDt < .5 && !SERVER_PAGE) {
    perfT += rawDt; perfN++;
    if (perfT >= 1.5) {
      const avg = perfT / perfN;
      if (avg > .024) {
        if (renderCap > 1 && DPR > 1) { renderCap = avg > .05 ? 1 : Math.max(1, Math.min(renderCap, DPR) - .5); resize(); }
        else lowFx = true;
      }
      perfT = 0; perfN = 0;
    }
  }
  nextFrame();
}

// Validate a saved night only now, after every file has loaded: validRun() checks against tables defined
// throughout the game (upgrades, weapons, relics, daily modifiers). Doing it earlier silently dropped saves.
normalizeLooks(); Object.assign(meta.look, resolveClashes(meta.look));
I18n.start(); // 0.30.1: the chosen language (English needs nothing)
for (const k in meta.inv) if (!ITK[k]) delete meta.inv[k]; meta.boostNext = meta.boostNext.filter(k => ITK[k] && ITK[k].cat === 'boost'); // 0.22: only known items // the wardrobe, once every file has added its items
try { meta.run = validRun(meta.run); } catch (e) { console.error('saved night dropped:', e); meta.run = null; }
if (cleanName(meta.profile.name).error) meta.profile.name = 'Keeper'; // names that break the rules fall back to the default
applyGfx(); applyMotion();
renderMute();
startIconWatch(document.body); // 0.16.1: the game's own icons in place of system emoji (02b-icons.js)
// The canvas draws text in the game's fonts; until they have loaded it would fall back to a system font (a different
// shape on every platform). Load them first, then measure the layout again.
if (document.fonts && document.fonts.load) Promise.all(['18px "Jersey 10"', '700 18px "Pixelify Sans"'].map(f => document.fonts.load(f))).then(() => { fontsReady = true; resize(); measureHud(); refreshUI(true); }).catch(() => { fontsReady = true; });
refreshUI(true);
checkAway(true);
