/* ---------- the human check (hCaptcha), when the project asks for one ----------
   LK_CLOUD.captcha is the public sitekey. Supabase then refuses sign-up, sign-in, new codes and password resets without
   a fresh token, so those screens show the check. Its script loads only when one of them opens. */
const Captcha = {
  id: null, loading: null,
  on: () => !!(LK_CLOUD && LK_CLOUD.captcha),
  load() {
    if (window.hcaptcha) return Promise.resolve();
    if (!this.loading) this.loading = new Promise((res, rej) => {
      window.lkCaptchaReady = res;
      const s = document.createElement('script'); s.src = 'https://js.hcaptcha.com/1/api.js?render=explicit&onload=lkCaptchaReady'; s.async = true;
      s.onerror = () => { this.loading = null; rej(new Error('The human check could not load. Check your connection and try again.')); };
      document.head.append(s);
    });
    return this.loading;
  },
  box() { // a fresh check for the screen being drawn (tokens work once)
    if (!this.on()) return '';
    if (this.id !== null && window.hcaptcha) { try { hcaptcha.remove(this.id); } catch (e) { /* already gone */ } }
    this.id = null;
    const d = el('div', { className: 'acCaptcha' });
    this.load().then(() => { if (d.isConnected) this.id = hcaptcha.render(d, { sitekey: LK_CLOUD.captcha, theme: 'dark' }); }).catch(e => { d.textContent = e.message; });
    return d;
  },
  token() {
    if (!this.on()) return undefined;
    const t = this.id !== null && window.hcaptcha ? hcaptcha.getResponse(this.id) : '';
    if (!t) throw new Error('Tick "I am human" first.');
    return t;
  },
};

/* ---------- the device-or-cloud choice ---------- */
function syncSide(label, when, s, dev) {
  const d = document.createElement('div'); d.className = 'syncSide';
  const h = document.createElement('b'); h.textContent = label; d.append(h);
  const lines = [when ? `Saved ${new Date(when).toLocaleString()}` : '', dev ? `On ${dev}` : '', `Level ${s.level || 1} · best wave ${s.best || 0}`, `${fmt(s.embers || 0)} embers · ${s.regions || 0} regions cleared · ${s.runs || 0} nights`];
  for (const t of lines.filter(Boolean)) { const p = document.createElement('p'); p.textContent = t; d.append(p); }
  return d;
}
// 0.29: the save choice appears only on the plain home screen (no other screen open, no night): never in the middle of something
const syncChoiceNow = () => mode === 'home' && ![...document.querySelectorAll('section.sheet:not([hidden])')].some(s => s.id !== 'syncChoice') && !document.querySelector('#appDialog:not([hidden])');
function showSyncChoice() {
  const c = Cloud.pending; if (!c) return;
  const box = $('#syncSides'); box.textContent = '';
  const mine = { level: levelOf(meta.profile.xp), best: meta.best, embers: meta.embers, regions: REGIONS.filter(r => meta.world.cleared[r.id]).length, runs: meta.runs };
  box.append(syncSide('This device', meta.last, mine, ''), syncSide('Cloud save', c.updated_at, c.summary || {}, c.device || ''));
  $('#syncChoice').hidden = false;
}
$('#bUseCloud').onclick = () => Cloud.choose('cloud');
$('#bUseDevice').onclick = () => Cloud.choose('device');
$('#bSyncLater').onclick = () => { $('#syncChoice').hidden = true; }; // asked again next time at home

/* ---------- the Account screen ----------
   0.14.1: show/hide passwords with the rules ticked off as you type, Enter submits, code boxes use the number keypad
   (and fill from the email on phones that offer it), a resend timer, the last email remembered, an unconfirmed account
   taken straight to its code, name changes reaching your public profile, sign out everywhere, and your data to keep. */
let acView = 'main', acEmail = '', acMsg = '', acBackTo = 'profile', acResendAt = 0, acOk = false;
const AC_MAIL_KEY = 'lantern-keeper-last-email';
try { acEmail = Platform.load(AC_MAIL_KEY) || ''; } catch (e) { acEmail = ''; }
const acBody = () => $('#acBody');
