// Enter in a field presses the screen's main button
function wireEnter(box) { for (const i of box.querySelectorAll('input')) i.addEventListener('keydown', e => { if (e.key !== 'Enter') return; e.preventDefault(); const b = box.querySelector('button.primary, button.danger'); if (b && !b.disabled) b.click(); }); }
// Everything the account holds, as a file (desktop and web) or copied (Android)
async function acDownload() {
  const g = await Cloud.call('save-sync', { action: 'get' }); if (g.status !== 200) throw new Error(g.body.error || 'The cloud save could not be read.');
  const { data: prof } = await Cloud.sb.from('profiles').select('*').eq('id', Cloud.user.id).maybeSingle(); // (0.29: my row only)
  const out = { exported: new Date().toISOString(), email: Cloud.user.email, profile: prof || null, cloudSave: g.body.save || null, revision: g.body.rev || 0, friends: (Social.friends || []).map(f => f.name || f.id), blocked: [...(Social.blocks || [])] };
  const text = JSON.stringify(out, null, 2);
  if (Platform.kind === 'android' || Platform.kind === 'ios') {
    await navigator.clipboard.writeText(text); acMsg = 'Your data was copied. Paste it into a note or an email to keep it.'; acOk = true; return;
  }
  const a = el('a', { href: URL.createObjectURL(new Blob([text], { type: 'application/json' })), download: `lantern-keeper-data-${new Date().toISOString().slice(0, 10)}.json` });
  document.body.append(a); a.click(); a.remove(); acMsg = 'Your data was saved as a file.'; acOk = true;
}
// A gentle prompt on the home screen for players without an account (after a few nights, and dismissable).
function renderAccountHint() {
  const h = $('#acHint'); if (!h) return;
  h.hidden = !(Cloud.on() && !Cloud.user && meta.runs >= 3 && !meta.tips.acHint && mode === 'home');
}
function openAccount() { acView = 'main'; acMsg = ''; acBackTo = 'profile'; show('account'); renderAccount(); }
$('#bAccount').onclick = openAccount;
$('#bAcClose').onclick = () => { if (acBackTo === 'store') { show('store'); renderStore(); } else if (acBackTo === 'coop') { show('coop'); renderCoop(); } else if (acBackTo === 'pvp') { openPvp(); } else { show('profile'); renderProfile(); } };
$('#bAcHint').onclick = () => { meta.tips.acHint = 1; save(); openAccount(); };
$('#bAcHintX').onclick = () => { meta.tips.acHint = 1; save(); renderAccountHint(); };
setInterval(() => { if (!$('#account').hidden) $('#acStatus').textContent = Cloud.statusText(); renderAccountHint(); }, 5000);
Cloud.init(); renderAccountHint();

// Terms and privacy links (the hosted pages; set in config/cloud.json)
function extLink(e) { const a = e.target.closest('[data-ext]'); if (!a || !a.closest('#acBody')) return; e.preventDefault(); const u = LK_CLOUD[a.dataset.ext + 'Url']; if (u) Platform.openExternal(u); }
document.addEventListener('click', extLink); // 0.26: links drawn inside the account form (Terms, Privacy Policy)
for (const a of document.querySelectorAll('[data-ext]')) a.onclick = e => { e.preventDefault(); const u = LK_CLOUD[a.dataset.ext + 'Url']; if (u) Platform.openExternal(u); else { acMsg = 'The ' + (a.dataset.ext === 'terms' ? 'Terms of Service' : 'Privacy Policy') + ' will be linked here once it is online. Ask l4nternkeeper@gmail.com for a copy.'; renderAccount(); } };


