    const { data, error } = await Cloud.sb.rpc('lumens_spend', { item_slot: slot, item_id: id, request_id: rid });
    if (error) { if (!/fetch|network|timeout/i.test(error.message || '')) delete this.pending[key]; throw new Error(acErrText(error)); } // a dropped connection: the retry reuses the id
