    const { data, error } = await Cloud.sb.rpc('lumens_spend_collection', { col_id: id, request_id: rid });
    if (error) { if (!/fetch|network|timeout/i.test(error.message || '')) delete this.pending[key]; throw new Error(acErrText(error)); }
