    if (this.cur && this.cur.id === row.id && this.cur.rev === row.rev && this.cur.status === row.status) return; // only "seen" times moved
    if (!this.cur && row.status !== 'invited' && !['done', 'cancelled'].includes(row.status)) return;
    if (this.cur && this.cur.id !== row.id && row.status !== 'invited') return;
