    const rows = ITEMS.filter(it => it.tradable && (itemCount(it.id) || Trade.chest[it.id])).map(it => {
      const inC = Trade.chest[it.id] || 0, inS = itemCount(it.id), offered = T ? (T.mine[it.id] || 0) : 0;
      return tradeItemRow(it, `<small>Satchel ${inS} · Chest ${inC}${offered ? ` (${offered} offered)` : ''}</small>
        <button class="btn small" data-mv="${it.id}" data-n="1" ${inS && inC < 999 ? '' : 'disabled'} ${dis} aria-label="Put one ${esc(it.name)} in the chest">Put in</button>
        <button class="btn small ghost" data-mv="${it.id}" data-n="-1" ${inC - offered > 0 && inS < 99 ? '' : 'disabled'} ${dis} aria-label="Take one ${esc(it.name)} out">Take out</button>`); });
