  const facts = [sc.lh && sc.lh.name ? `Lighthouse: ${sc.lh.name}` : '', fav.w ? `Favourite weapon: ${fav.w}` : '', fav.k ? `Favourite keeper: ${fav.k}` : '', fav.r ? `Favourite region: ${fav.r}` : '', `Keeping watch since ${new Date(p.created_at).toLocaleDateString()}`].filter(Boolean);
