  if (!P) { add(sEl('p', { className: 'sub', textContent: 'A party keeps up to four keepers together: a party chat, and one tap to start co-op.' }), sBtn('Create a party', () => Social.createParty(), 'btn primary')); return; }
  const lead = P.leader === Social.me();
  add(sEl('h3', { className: 'sec', textContent: `Your party (${P.members.length} / 4)` }));
  for (const id of P.members) add(personRow(id, [sEl('span', { className: 'muted', textContent: id === P.leader ? 'Leader' : id === Social.me() ? 'You' : '' })]));
  const btns = [sBtn('Party chat', async () => { Social.channel = 'party:' + P.id; await Social.loadChannel(Social.channel); socTab = 'chat'; }), sBtn('Leave party', () => Social.leaveParty(), 'btn small ghost')];
