    add(sEl('div', { className: 'wk goal' }, [sEl('div', {}, [sEl('span', { textContent: g.title }), sEl('span', { className: 'muted', textContent: `${fmt(g.progress)} / ${fmt(g.target)}` })]), bar, sEl('p', { className: 'acNote', textContent: `Reward: ${g.reward}. Ends ${new Date(g.ends_at).toLocaleDateString()}.` })]));
