  add(sEl('div', { className: 'saveBtns' }, [sBtn('Refresh', () => { socMod = null; }), sBtn('Slow mode 10s (Community)', () => Social.mod('slow', { channel: 'global', seconds: 10 }).then(() => 'Slow mode on.')), sBtn('Slow mode off', () => Social.mod('slow', { channel: 'global', seconds: 0 }).then(() => 'Slow mode off.'))]));
