  aggressive: { name: 'Aggressive', ico: 'fire', desc: 'Damage and fire rate.', tags: { core: 4, crit: 3, volley: 2 }, keepers: ['smith', 'ranger', 'hunter'], weapons: ['repeater', 'flare', 'storm'], acc: .62 },
  control: { name: 'Control', ico: 'snow', desc: 'Slows, stuns and frozen lanterns.', tags: { frost: 5 }, keepers: ['monk', 'bellbearer', 'caller'], weapons: ['frost', 'tide', 'glacier'], acc: .72 },
  glass: { name: 'Glass cannon', ico: 'burst', desc: 'Huge hits, thin walls.', tags: { core: 4, crit: 5 }, keepers: ['ranger', 'smith'], weapons: ['cannon', 'comet', 'obsidianedge'], charms: ['edgestone', 'glasseye'], acc: .6 },
