  maybeFound() { if (this.phase === 'meet' && this.helloed && this.snaps && this.snaps[0] && this.snaps[1]) { clearInterval(this.helloT); this.hello(); this.go('found'); this.sendSnapCheck(); } },
  // both screens prove they draw the same two keepers: hashes (and the snapshots, to name what differs)
