    const S = this.sides, share = S ? [S[0].hp / S[0].max, S[1].hp / S[1].max] : [1, 1], w = pvpResolveFall(a, b, share);
    const fall = { why: !a.alive && !b.alive ? 'double' : 'fell', ph, prog: [a.alive ? null : a.prog, b.alive ? null : b.prog], alive: [a.alive, b.alive] };
