    const waves = ph ? PVP_CFG.survivalWaves[ph - 1] : PVP_CFG.buildWaves;
    const risk = this.aiRisk != null ? this.aiRisk : ph ? [0, .05, .08, .12][ph] + (low ? .08 : 0) : .02; // aiRisk: the tests fix it
    if (Math.random() < risk) { f.wave = Math.floor(Math.random() * waves); aiPvpReact('scared'); return this.foeFell(ph, +(f.wave + Math.random() * .9).toFixed(3)); }
    const n = ph ? 1 : PVP_CFG.buildWaves; for (let i = 0; i < n; i++) f.seq.push(pvpAiPick(f.style, f.seq, low));
    f.ph = ph; f.wave = waves; this.foeDone[ph] = 1; this.foeRes[ph] = { alive: true, perfect: ph > 0 && Math.random() < .3 };
