          if (data && data.status !== 'live') { Object.assign(res, { status: data.status, delta: data.delta, rating: data.rating }); if (data.rating) { this.rating = Object.assign(this.rating || {}, { rating: data.rating }); n.pvpbest = Math.max(n.pvpbest || 0, data.rating); save(); checkAch(); } if (data.status === 'done' && won && !draw && !friendly) earn(250, false); if (here()) showPvpEnd(true); break; }
